/** Seção "estilos". */
export const ARTICLES: DocArticle[] = [
  { id: "arquitetura-monolitica", section: "estilos", level: 0, icon: "deployed_code", minutes: 12,
    title: ["Arquitetura monolítica", "Monolithic architecture"],
    summary: ["Tudo em um só programa: simples de construir, simples de operar, e mais forte do que sua fama.", "Everything in one program: simple to build, simple to run, and stronger than its reputation."],
    body: [
      p(["Quando uma ideia vira produto, a primeira pergunta de arquitetura costuma ser como organizar o código. Existe uma resposta que quase todo mundo já usou, muitas vezes sem dar nome: colocar tudo no mesmo projeto, compilar como uma unidade só e publicar de uma vez. Esse é o **monolito**: uma aplicação em que cadastro de usuários, catálogo, pedidos, pagamento e notificações vivem no mesmo código-fonte, são empacotados no mesmo artefato (um JAR, uma imagem de contêiner, um conjunto de arquivos) e normalmente conversam com um único banco de dados.", "When an idea becomes a product, the first architecture question is usually how to organize the code. There is an answer almost everyone has used, often without naming it: put everything in the same project, build it as a single unit and ship it all at once. That is the **monolith**: an application in which user sign-up, catalog, orders, payment and notifications live in the same source code, are packaged in the same artifact (a JAR, a container image, a set of files) and usually talk to a single database."]),
      p(["A palavra 'monolito' ganhou tom pejorativo nos últimos anos, por causa da popularidade dos microsserviços. Isso é um equívoco: monolito descreve a **forma de publicação** (uma unidade), não a qualidade interna do código. Existem monolitos limpos, bem divididos e fáceis de manter, e existem sistemas distribuídos em dezenas de serviços que são uma bagunça. Entender o monolito de verdade, com seus pontos fortes e seus limites, é a base para decidir quando ficar nele e quando sair.", "The word 'monolith' took on a pejorative tone in recent years because of the popularity of microservices. That is a misunderstanding: monolith describes the **deployment shape** (one unit), not the internal quality of the code. There are clean, well-divided, easy-to-maintain monoliths, and there are systems spread over dozens of services that are a mess. Understanding the monolith properly, with its strengths and limits, is the basis for deciding when to stay and when to leave."]),
      fig(["Um monolito típico: uma unidade de deploy e um banco", "A typical monolith: one deployment unit and one database"],
        [[node("web", ["Navegador ou app", "Browser or app"], "client")], [node("lb", ["Balanceador", "Load balancer"], "edge")], [node("app", ["Aplicação monolítica (usuários, pedidos, pagamento, estoque)", "Monolithic app (users, orders, payment, stock)"], "service")], [node("db", ["Banco único", "Single database"], "data"), node("ch", "Cache", "cache")]],
        [edge("web", "lb"), edge("lb", "app"), edge("app", "db", ["SQL", "SQL"]), edge("app", "ch", ["leituras quentes", "hot reads"], { dashed: true })]),
      h(["Como um monolito é organizado por dentro", "How a monolith is organized inside"]),
      p(["A organização interna mais comum é em **camadas**. A camada de apresentação recebe a requisição (controladores HTTP, telas renderizadas no servidor ou uma API consumida por um front-end separado). A camada de negócio contém as regras: calcular frete, aplicar cupom, validar que o estoque basta. A camada de dados abstrai o acesso ao banco, em geral por meio de repositórios ou de um ORM. Cada camada só deveria falar com a de baixo, o que mantém a regra de negócio livre de detalhes de HTTP e de SQL.", "The most common internal organization is in **layers**. The presentation layer receives the request (HTTP controllers, server-rendered pages or an API consumed by a separate front end). The business layer holds the rules: computing shipping, applying a coupon, checking that stock suffices. The data layer abstracts database access, usually through repositories or an ORM. Each layer should only talk to the one below, which keeps business rules free of HTTP and SQL details."]),
      p(["Todas as chamadas entre partes do sistema são **chamadas de função dentro do mesmo processo**. Isso tem consequências profundas: não há serialização, não há rede, não há timeout nem retentativa entre o módulo de pedidos e o de estoque. Uma chamada leva nanossegundos ou microssegundos, e ou funciona ou lança uma exceção na mesma pilha de execução. A maior parte da simplicidade do monolito vem daqui.", "All calls between parts of the system are **function calls inside the same process**. This has deep consequences: there is no serialization, no network, no timeout or retry between the orders module and the stock module. A call takes nanoseconds or microseconds, and it either works or throws an exception on the same call stack. Most of the monolith's simplicity comes from here."]),
      code(`request: POST /orders
  OrderController.create()          # presentation layer
    -> OrderService.place(cart)     # business layer
         -> StockService.reserve()  # plain function call
         -> PaymentService.charge() # plain function call
         -> OrderRepository.save()  # data layer
  all inside ONE database transaction: commit or rollback together`),
      h(["Variações do monolito", "Variations of the monolith"]),
      p(["Nem todo monolito é igual. A diferença está na disciplina interna, e é ela que determina se o sistema envelhece bem ou vira um emaranhado.", "Not every monolith is the same. The difference lies in internal discipline, and that decides whether the system ages well or turns into a tangle."]),
      table([["Variação", "Variation"], ["Como é", "What it is like"], ["Risco principal", "Main risk"]],
        [["Monolito em camadas", "Layered monolith"], ["Divide por camada técnica (controllers, services, repositories) dentro de um único projeto.", "Divides by technical layer (controllers, services, repositories) inside one project."], ["Qualquer funcionalidade toca todas as camadas, e os domínios se misturam.", "Every feature touches all layers, and domains get mixed."]],
        [["Monolito modular", "Modular monolith"], ["Divide por área de negócio (pedidos, catálogo, faturamento); cada módulo tem interface pública e esconde seus dados.", "Divides by business area (orders, catalog, billing); each module has a public interface and hides its data."], ["Exige disciplina e ferramentas para impedir atalhos entre módulos.", "Requires discipline and tooling to stop shortcuts between modules."]],
        [["Grande bola de lama", "Big ball of mud"], ["Sem fronteiras: qualquer classe chama qualquer outra e todos leem todas as tabelas.", "No boundaries: any class calls any other and everyone reads every table."], ["Mudanças viram roleta; ninguém entende o impacto de tocar em algo.", "Changes become a lottery; nobody understands the impact of touching anything."]],
        [["Monolito de implantação", "Deployment monolith"], ["Código dividido em bibliotecas ou projetos, mas tudo publicado junto.", "Code split into libraries or projects, but everything shipped together."], ["Parece modular, porém continua acoplado no deploy e, muitas vezes, no banco.", "Looks modular, yet remains coupled at deploy time and often in the database."]],
      ),
      p(["O estado desejável para a maioria das equipes é o **monolito modular**. Ele preserva as vantagens operacionais do monolito (um deploy, transações simples) e acrescenta o que é bom nos microsserviços: fronteiras claras entre áreas de negócio. Na prática, um módulo só enxerga os outros por uma interface pública, e as tabelas de cada módulo são privadas dele. Essa regra pode ser verificada automaticamente: ferramentas de análise de dependências e regras de arquitetura nos testes falham o build quando alguém importa uma classe interna de outro módulo.", "The desired state for most teams is the **modular monolith**. It keeps the operational advantages of the monolith (one deploy, simple transactions) and adds what is good about microservices: clear boundaries between business areas. In practice a module only sees the others through a public interface, and each module's tables are private to it. This rule can be checked automatically: dependency-analysis tools and architecture rules in tests fail the build when someone imports an internal class from another module."]),
      code(`// orders/index.ts : the ONLY file other modules may import
export interface OrdersApi {
  place(cart: Cart): Promise<OrderId>;
  cancel(id: OrderId): Promise<void>;
}
export { createOrdersApi } from "./internal/create-orders-api";

// billing/internal/invoice.ts
import { OrdersApi } from "../../orders";          // OK: public API
// import { OrderRow } from "../../orders/internal/db"; // forbidden

// architecture test (pseudo-rule, run in CI)
// rule: nothing outside "orders/" may import "orders/internal/**"`),
      h(["Implantação e escala", "Deployment and scaling"]),
      p(["O deploy de um monolito é simples de descrever: compilar, rodar os testes, gerar o artefato e substituí-lo em produção. Em sistemas pequenos pode ser um único servidor. Em sistemas maiores, o artefato é copiado para várias instâncias atrás de um balanceador de carga, com uma estratégia de substituição gradual (*rolling update*) ou de duas versões lado a lado (*blue-green*) para evitar indisponibilidade.", "Deploying a monolith is simple to describe: build, run the tests, produce the artifact and replace it in production. In small systems it can be a single server. In larger systems the artifact is copied to several instances behind a load balancer, with a gradual replacement strategy (*rolling update*) or two versions side by side (*blue-green*) to avoid downtime."]),
      p(["Sobre a escala, há dois movimentos. A **escala vertical** é dar uma máquina maior ao mesmo processo (mais CPU, mais memória): é a forma mais barata de começar e funciona surpreendentemente longe, mas tem teto e um ponto único de falha. A **escala horizontal** é rodar várias cópias idênticas da aplicação. Ela só funciona direito quando a aplicação é *stateless*: sessões, arquivos enviados e filas precisam morar fora do processo (em Redis, em armazenamento de objetos, no banco). Com isso, qualquer cópia atende qualquer requisição, e dobrar a capacidade é dobrar o número de cópias.", "On scaling there are two moves. **Vertical scaling** means giving the same process a bigger machine (more CPU, more memory): it is the cheapest way to start and works surprisingly far, but it has a ceiling and a single point of failure. **Horizontal scaling** means running several identical copies of the application. It only works properly when the application is *stateless*: sessions, uploaded files and queues must live outside the process (in Redis, object storage, the database). With that, any copy serves any request, and doubling capacity is doubling the number of copies."]),
      p(["O limite de escala do monolito costuma ser o **banco de dados**, não a aplicação. Replicas de leitura, cache, índices bem escolhidos e, mais tarde, particionamento (*sharding*) empurram esse limite. O ponto de atenção é a **escala uniforme**: se só o módulo de busca está sobrecarregado, é preciso replicar a aplicação inteira, carregando junto o consumo de memória de tudo que não precisava crescer.", "The monolith's scaling limit is usually the **database**, not the application. Read replicas, caching, well-chosen indexes and, later, partitioning (*sharding*) push that limit out. The point to watch is **uniform scaling**: if only the search module is overloaded, you have to replicate the entire application, carrying along the memory footprint of everything that did not need to grow."]),
      h(["Vantagens", "Advantages"]),
      ul(
        ["**Simplicidade de desenvolvimento**: uma base de código, um repositório, um build. Um novo membro da equipe clona, roda e já tem o sistema inteiro funcionando.", "**Development simplicity**: one codebase, one repository, one build. A new team member clones, runs and already has the whole system working."],
        ["**Chamadas locais**: sem rede entre módulos, não existem timeouts, retentativas, serialização nem problemas de versão de contrato entre as partes.", "**Local calls**: with no network between modules, there are no timeouts, retries, serialization or contract-version problems between the parts."],
        ["**Transações ACID**: gravar pedido, itens e baixa de estoque na mesma transação é uma linha de código. A consistência é garantida pelo banco, não por um protocolo distribuído.", "**ACID transactions**: writing the order, its items and the stock decrement in the same transaction is one line of code. Consistency is guaranteed by the database, not by a distributed protocol."],
        ["**Depuração e testes**: um depurador, um stack trace completo, testes de integração que sobem tudo no computador do desenvolvedor.", "**Debugging and testing**: one debugger, a complete stack trace, integration tests that bring everything up on the developer's machine."],
        ["**Operação barata**: um pipeline, um conjunto de logs, um painel de métricas. Equipes pequenas operam o sistema sem uma plataforma dedicada.", "**Cheap operation**: one pipeline, one set of logs, one metrics dashboard. Small teams run the system without a dedicated platform."],
        ["**Refatoração fácil**: renomear uma função ou mover uma responsabilidade é uma mudança de código verificada pelo compilador, e não uma migração coordenada entre serviços.", "**Easy refactoring**: renaming a function or moving a responsibility is a code change checked by the compiler, not a coordinated migration across services."],
      ),
      h(["Desvantagens e limites", "Disadvantages and limits"]),
      ul(
        ["**Deploy acoplado**: uma alteração pequena exige publicar tudo, e um bug em um módulo pode derrubar o processo inteiro (um vazamento de memória no módulo de relatórios afeta o checkout).", "**Coupled deploys**: a small change requires shipping everything, and a bug in one module can bring down the whole process (a memory leak in the reports module affects checkout)."],
        ["**Escala uniforme**: não dá para dar mais recursos só ao que está sobrecarregado.", "**Uniform scaling**: you cannot give more resources only to what is overloaded."],
        ["**Tecnologia única**: linguagem, framework e versão de bibliotecas valem para todos; atualizar o framework é uma tarefa que toca o sistema inteiro.", "**Single technology**: language, framework and library versions apply to everyone; upgrading the framework is a task that touches the entire system."],
        ["**Crescimento da equipe**: com dezenas de pessoas no mesmo repositório, aumentam os conflitos de merge, o tempo de build e de testes e a dificuldade de saber quem é dono de quê.", "**Team growth**: with dozens of people in the same repository, merge conflicts, build and test times and the difficulty of knowing who owns what all increase."],
        ["**Erosão das fronteiras**: sem disciplina, o código tende ao emaranhado, e cada atalho feito por pressa de entrega se torna uma dependência permanente.", "**Boundary erosion**: without discipline the code drifts toward a tangle, and every shortcut taken to meet a deadline becomes a permanent dependency."],
        ["**Risco de falha total**: um único processo é um único domínio de falha. Sem isolamento interno, uma falha vira indisponibilidade geral.", "**Total-failure risk**: a single process is a single failure domain. Without internal isolation, one failure becomes a general outage."],
      ),
      h(["Quando escolher e quando reconsiderar", "When to choose it and when to reconsider"]),
      p(["O monolito é a escolha certa quando o domínio ainda está sendo descoberto, a equipe é pequena (até algumas dezenas de pessoas, dependendo da maturidade) e a prioridade é entregar e aprender rápido. Nesse estágio, os limites corretos entre serviços ainda não são conhecidos, e errá-los em um sistema distribuído é muito mais caro do que errá-los dentro de um monolito, onde mover código entre módulos é trivial. Ele também é adequado para sistemas internos, ferramentas administrativas, produtos com carga previsível e qualquer caso em que a consistência forte seja um requisito central.", "The monolith is the right choice when the domain is still being discovered, the team is small (up to a few dozen people, depending on maturity) and the priority is to deliver and learn fast. At that stage the correct boundaries between services are not yet known, and getting them wrong in a distributed system is far costlier than getting them wrong inside a monolith, where moving code between modules is trivial. It also fits internal systems, admin tools, products with predictable load and any case where strong consistency is a core requirement."]),
      p(["Vale reconsiderar quando surgem sinais concretos: equipes que se bloqueiam mutuamente nos deploys, builds e testes que levam tempo demais, um componente com necessidade de escala ou de tecnologia radicalmente diferente (processamento de vídeo, busca, aprendizado de máquina), ou um módulo instável que precisa ser isolado. Mesmo nesses casos, o caminho costuma ser primeiro tornar o monolito modular e só então extrair os módulos que realmente se beneficiam de viver sozinhos.", "It is worth reconsidering when concrete signs appear: teams blocking each other on deploys, builds and tests taking too long, a component with radically different scale or technology needs (video processing, search, machine learning), or an unstable module that must be isolated. Even then, the path is usually to first make the monolith modular and only then extract the modules that truly benefit from living alone."]),
      h(["Casos reais", "Real-world cases"]),
      p(["Muitos produtos grandes começaram e cresceram como monolitos. A Shopify é frequentemente citada por manter uma grande aplicação Rails organizada como monolito modular, em vez de dividi-la em centenas de serviços. O Stack Overflow ficou conhecido por servir um tráfego enorme com um número pequeno de servidores rodando uma aplicação monolítica. Esses exemplos mostram que o tamanho do tráfego, sozinho, não obriga ninguém a adotar microsserviços; o que pesa é a organização das equipes e o formato do problema.", "Many large products started and grew as monoliths. Shopify is often cited for keeping a large Rails application organized as a modular monolith instead of splitting it into hundreds of services. Stack Overflow became known for serving enormous traffic with a small number of servers running a monolithic application. These examples show that traffic volume alone does not force anyone into microservices; what matters is how teams are organized and the shape of the problem."]),
      h(["Erros comuns", "Common mistakes"]),
      ul(
        ["Tratar o monolito como bagunça aceitável: sem fronteiras internas, ele envelhece mal e a migração futura fica impossível.", "Treating the monolith as acceptable mess: without internal boundaries it ages badly and a future migration becomes impossible."],
        ["Compartilhar tabelas livremente entre módulos: o banco vira a API não documentada do sistema, e qualquer mudança de esquema quebra algo distante.", "Sharing tables freely between modules: the database becomes the system's undocumented API, and any schema change breaks something far away."],
        ["Guardar estado na memória do processo (sessões, caches locais com dados mutáveis) e depois descobrir que não consegue replicar a aplicação.", "Keeping state in process memory (sessions, local caches of mutable data) and later discovering you cannot replicate the application."],
        ["Migrar para microsserviços por modismo, antes de ter equipe, plataforma de entrega e observabilidade para sustentar a mudança.", "Migrating to microservices by fashion, before having the team, delivery platform and observability to sustain the change."],
        ["Deixar o tempo de build e de testes crescer sem controle: um pipeline de uma hora destrói o ciclo de feedback. Paralelize, use cache de build e divida a suíte.", "Letting build and test time grow unchecked: a one-hour pipeline destroys the feedback loop. Parallelize, use build caches and split the suite."],
      ),
      h(["Resumo", "Summary"]),
      ul(
        ["Monolito é uma forma de publicação: um código, um artefato, normalmente um banco.", "A monolith is a deployment shape: one codebase, one artifact, usually one database."],
        ["Chamadas locais e transações ACID são sua maior força.", "Local calls and ACID transactions are its greatest strength."],
        ["Escala bem na horizontal quando é stateless; o limite costuma ser o banco.", "It scales well horizontally when stateless; the limit is usually the database."],
        ["O monolito modular une simplicidade operacional e fronteiras claras.", "The modular monolith combines operational simplicity and clear boundaries."],
        ["Os problemas aparecem com muitos times, deploys acoplados e necessidades de escala muito desiguais.", "Problems appear with many teams, coupled deploys and very uneven scaling needs."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Monolito escala?** Sim. Com instâncias stateless atrás de um balanceador e um banco bem dimensionado, atende milhões de usuários. O que ele não faz é escalar partes isoladas.", "**Does a monolith scale?** Yes. With stateless instances behind a load balancer and a well-sized database it serves millions of users. What it cannot do is scale isolated parts."],
        ["**Todo monolito é um problema de código legado?** Não. Legado é falta de testes e de fronteiras, não o estilo de deploy.", "**Is every monolith a legacy-code problem?** No. Legacy is a lack of tests and boundaries, not the deployment style."],
        ["**Posso ter vários bancos em um monolito?** Pode, por exemplo um banco transacional e um de busca, mas cada banco extra reduz a simplicidade das transações.", "**Can I have several databases in a monolith?** You can, for example a transactional database and a search one, but each extra database reduces transaction simplicity."],
        ["**Começar já com microsserviços ajuda a escalar depois?** Raramente. O mais comum é pagar o custo operacional cedo e errar as fronteiras.", "**Does starting with microservices help scale later?** Rarely. The usual result is paying the operational cost early and getting the boundaries wrong."],
      ),
      tip(["O monolito é o ponto de partida certo para quase todo produto novo. O problema raramente é o monolito em si, e sim um monolito sem fronteiras internas, onde tudo conhece tudo. Cuide das fronteiras desde o primeiro dia e a decisão de dividir, se vier, será barata.", "The monolith is the right starting point for almost every new product. The problem is rarely the monolith itself, but a monolith without internal boundaries, where everything knows everything. Take care of the boundaries from day one and the decision to split, if it comes, will be cheap."]),
    ] },

  { id: "microsservicos", section: "estilos", level: 1, icon: "hub", minutes: 14,
    title: ["Microsserviços", "Microservices"],
    summary: ["Dividir o sistema em serviços pequenos e independentes, e o preço que isso cobra.", "Splitting the system into small, independent services, and the price that comes with it."],
    body: [
      p(["Imagine uma loja virtual com duzentos engenheiros trabalhando no mesmo repositório. Cada publicação exige coordenar dezenas de pessoas, um erro no módulo de recomendações derruba o checkout, e a busca precisa de dez vezes mais servidores do que o cadastro, mas só é possível multiplicar a aplicação inteira. A arquitetura de **microsserviços** nasceu como resposta a esse tipo de dor: em vez de uma aplicação grande, o sistema é um conjunto de serviços pequenos, cada um responsável por uma capacidade do negócio, com seu próprio código, seu próprio ciclo de deploy e, idealmente, seu próprio banco de dados.", "Imagine an online store with two hundred engineers working in the same repository. Every release requires coordinating dozens of people, a bug in the recommendations module takes down checkout, and search needs ten times more servers than sign-up, yet the only option is multiplying the entire application. The **microservices** architecture was born as an answer to this kind of pain: instead of one large application, the system is a set of small services, each responsible for one business capability, with its own code, its own deploy cycle and, ideally, its own database."]),
      p(["Os serviços se comunicam por rede, por chamadas síncronas (HTTP/REST, gRPC) ou por mensagens assíncronas (filas, eventos). Cada serviço pode ser escrito na linguagem mais adequada, publicado várias vezes ao dia e escalado de modo independente. É importante entender, desde o início, que isso não é gratuito: o que era chamada de função vira chamada de rede, e o que era transação vira coordenação distribuída. Microsserviços trocam complexidade de código por complexidade de operação.", "Services communicate over the network, through synchronous calls (HTTP/REST, gRPC) or asynchronous messages (queues, events). Each service can be written in the most suitable language, deployed several times a day and scaled independently. It is important to understand from the start that this is not free: what used to be a function call becomes a network call, and what used to be a transaction becomes distributed coordination. Microservices trade code complexity for operational complexity."]),
      fig(["Visão geral: gateway na frente e um banco por serviço", "Overview: a gateway in front and one database per service"],
        [[node("cli", ["App e navegador", "App and browser"], "client")], [node("gw", "API Gateway", "edge")], [node("usr", ["Serviço de usuários", "Users service"], "service"), node("ord", ["Serviço de pedidos", "Orders service"], "service"), node("pay", ["Serviço de pagamento", "Payment service"], "service")], [node("dbu", ["Banco de usuários", "Users DB"], "data"), node("dbo", ["Banco de pedidos", "Orders DB"], "data"), node("dbp", ["Banco de pagamentos", "Payments DB"], "data")]],
        [edge("cli", "gw", "HTTPS"), edge("gw", "usr"), edge("gw", "ord"), edge("gw", "pay"), edge("usr", "dbu"), edge("ord", "dbo"), edge("pay", "dbp"), edge("ord", "pay", ["chama", "calls"], { dashed: true })]),
      h(["Características de um microsserviço", "Traits of a microservice"]),
      ul(
        ["**Responsabilidade única de negócio**: o serviço cuida de uma capacidade (faturamento, catálogo, frete) e não de uma camada técnica.", "**Single business responsibility**: the service handles one capability (billing, catalog, shipping), not a technical layer."],
        ["**Deploy independente**: publicar o serviço não exige publicar nenhum outro. Esse é o critério mais importante de todos.", "**Independent deployment**: shipping the service does not require shipping any other. This is the most important criterion of all."],
        ["**Dados próprios**: nenhum outro serviço lê ou escreve diretamente nas tabelas dele; o acesso é pela API do serviço.", "**Owned data**: no other service reads or writes its tables directly; access goes through the service's API."],
        ["**Contratos explícitos**: a interface pública (REST, gRPC, eventos) é versionada e mantida com compatibilidade.", "**Explicit contracts**: the public interface (REST, gRPC, events) is versioned and kept compatible."],
        ["**Propriedade de equipe**: uma equipe pequena é dona do serviço do início ao fim, incluindo operá-lo em produção.", "**Team ownership**: a small team owns the service end to end, including running it in production."],
        ["**Projetado para falhar**: assume que os vizinhos podem estar lentos ou fora do ar e se defende disso.", "**Designed for failure**: it assumes neighbors may be slow or down and defends itself accordingly."],
      ),
      h(["Como definir as fronteiras", "How to define the boundaries"]),
      p(["A decisão mais difícil e mais cara de errar é onde cortar. O erro clássico é dividir por camada técnica (um serviço de acesso a dados, outro de regras, outro de interface), o que obriga toda funcionalidade a atravessar todos os serviços. O caminho recomendado vem do **Domain-Driven Design**: identifique os **contextos delimitados** (*bounded contexts*), regiões do negócio em que cada termo tem um significado preciso. 'Cliente' no contexto de vendas (alguém com histórico de compras e preferências) não é o mesmo que 'cliente' no faturamento (um CNPJ com endereço fiscal e condições de pagamento). Cada contexto vira candidato a serviço, com seu próprio modelo.", "The hardest decision, and the costliest to get wrong, is where to cut. The classic mistake is splitting by technical layer (one data-access service, another for rules, another for the interface), which forces every feature to cross all services. The recommended path comes from **Domain-Driven Design**: identify the **bounded contexts**, regions of the business where each term has a precise meaning. 'Customer' in the sales context (someone with purchase history and preferences) is not the same as 'customer' in billing (a tax ID with a fiscal address and payment terms). Each context becomes a service candidate, with its own model."]),
      p(["Alguns testes práticos ajudam. Dá para mudar e publicar esse serviço sem coordenar com outra equipe? Uma funcionalidade típica exige alterar um serviço ou cinco? Dois serviços sempre mudam juntos? Eles precisam trocar dezenas de mensagens para completar um único pedido do usuário? Se a resposta indicar acoplamento forte, as fronteiras provavelmente estão no lugar errado. Comece com serviços maiores do que parece necessário: dividir depois é mais fácil do que juntar serviços mal cortados.", "A few practical tests help. Can you change and ship this service without coordinating with another team? Does a typical feature require changing one service or five? Do two services always change together? Do they need to exchange dozens of messages to complete a single user request? If the answer points to strong coupling, the boundaries are probably in the wrong place. Start with services larger than seems necessary: splitting later is easier than merging badly cut services."]),
      h(["Comunicação entre serviços", "Communication between services"]),
      p(["Há dois grandes estilos. Na comunicação **síncrona**, o chamador envia um pedido e espera a resposta: REST sobre HTTP é o mais difundido, e gRPC (com Protocol Buffers sobre HTTP/2) é comum entre serviços internos pelo menor custo de serialização e pelo contrato tipado. É simples de entender e de depurar, mas cria **acoplamento temporal**: se o serviço chamado está fora do ar ou lento, o chamador sofre junto. Uma cadeia de cinco chamadas síncronas, cada uma com 99,9% de disponibilidade, entrega no máximo cerca de 99,5% no conjunto.", "There are two broad styles. In **synchronous** communication the caller sends a request and waits for the answer: REST over HTTP is the most widespread, and gRPC (with Protocol Buffers over HTTP/2) is common between internal services thanks to lower serialization cost and a typed contract. It is simple to understand and debug, but creates **temporal coupling**: if the called service is down or slow, the caller suffers along. A chain of five synchronous calls, each with 99.9% availability, delivers at most about 99.5% overall."]),
      p(["Na comunicação **assíncrona**, o serviço publica uma mensagem ou evento em um broker (Kafka, RabbitMQ, SQS/SNS) e segue em frente; quem interessa processa depois. Isso desacopla no tempo e absorve picos, ao custo de consistência eventual e de fluxos mais difíceis de acompanhar. A regra prática: use chamadas síncronas quando o usuário espera a resposta para continuar (consultar o preço, validar um cartão) e eventos quando o efeito pode acontecer depois (enviar e-mail, atualizar o índice de busca, gerar nota fiscal).", "In **asynchronous** communication the service publishes a message or event to a broker (Kafka, RabbitMQ, SQS/SNS) and moves on; whoever cares processes it later. This decouples in time and absorbs spikes, at the cost of eventual consistency and flows that are harder to follow. The rule of thumb: use synchronous calls when the user waits for the answer to continue (looking up a price, validating a card) and events when the effect can happen later (sending email, updating the search index, issuing an invoice)."]),
      table([["Aspecto", "Aspect"], ["Síncrona (REST, gRPC)", "Synchronous (REST, gRPC)"], ["Assíncrona (eventos, filas)", "Asynchronous (events, queues)"]],
        [["Acoplamento temporal", "Temporal coupling"], ["Alto: os dois precisam estar no ar ao mesmo tempo.", "High: both must be up at the same time."], ["Baixo: o broker guarda a mensagem até o consumidor voltar.", "Low: the broker holds the message until the consumer returns."]],
        [["Resposta ao usuário", "Response to the user"], ["Imediata e com resultado.", "Immediate and with a result."], ["Confirmação de recebimento; o resultado vem depois.", "Acknowledgment of receipt; the result comes later."]],
        [["Consistência", "Consistency"], ["Mais próxima da imediata.", "Closer to immediate."], ["Eventual.", "Eventual."]],
        [["Depuração", "Debugging"], ["Mais direta (uma cadeia de chamadas).", "More direct (a chain of calls)."], ["Mais difícil (fluxo espalhado, exige correlação).", "Harder (scattered flow, needs correlation)."]],
        [["Picos de carga", "Load spikes"], ["Propagam-se pela cadeia.", "Propagate down the chain."], ["Absorvidos pela fila.", "Absorbed by the queue."]],
      ),
      h(["Dados: um banco por serviço", "Data: one database per service"]),
      p(["Se dois serviços compartilham o mesmo esquema, qualquer mudança de coluna exige coordenação entre eles e a independência de deploy desaparece. Por isso cada serviço é dono dos seus dados e ninguém acessa suas tabelas diretamente. Isso também libera a escolha: o catálogo pode usar um banco de documentos, o faturamento um relacional, a busca um índice próprio. O preço é que **consultas que cruzam serviços** deixam de ser um JOIN. As alternativas são compor a resposta no gateway ou em um serviço agregador (*API composition*), ou manter uma cópia de leitura alimentada por eventos (CQRS), aceitando que ela esteja alguns instantes atrasada.", "If two services share the same schema, any column change requires coordination between them and deploy independence disappears. That is why each service owns its data and nobody accesses its tables directly. It also frees the choice: the catalog can use a document database, billing a relational one, search its own index. The price is that **queries spanning services** stop being a JOIN. The alternatives are composing the answer in the gateway or in an aggregator service (*API composition*), or keeping a read copy fed by events (CQRS), accepting that it lags by a few moments."]),
      p(["O maior impacto é nas **transações**. Gravar um pedido, reservar estoque e cobrar o cartão deixou de caber em um único COMMIT. A solução é o padrão **saga**: uma sequência de transações locais, cada uma publicando um evento ou comando que dispara a próxima. Se um passo falha, executam-se **transações de compensação** que desfazem semanticamente os anteriores (estornar o pagamento, devolver o estoque). Há duas formas de coordenar: **coreografia**, em que cada serviço reage aos eventos dos outros sem um maestro, e **orquestração**, em que um serviço orquestrador diz a cada participante o que fazer. A coreografia é mais desacoplada, mas o fluxo fica implícito e difícil de enxergar; a orquestração deixa o fluxo explícito em um lugar só, com o custo de um ponto central de lógica.", "The greatest impact is on **transactions**. Writing an order, reserving stock and charging the card no longer fit in one COMMIT. The solution is the **saga** pattern: a sequence of local transactions, each publishing an event or command that triggers the next. If a step fails, **compensating transactions** semantically undo the previous ones (refund the payment, return the stock). There are two ways to coordinate: **choreography**, where each service reacts to the others' events with no conductor, and **orchestration**, where an orchestrator service tells each participant what to do. Choreography is more decoupled, but the flow becomes implicit and hard to see; orchestration makes the flow explicit in one place, at the cost of a central point of logic."]),
      fig(["Saga de pedido: sucesso e compensação", "Order saga: success and compensation"],
        [[node("o", ["Pedidos: cria pedido", "Orders: create order"], "service")], [node("s", ["Estoque: reserva itens", "Stock: reserve items"], "service")], [node("pg", ["Pagamento: cobra cartão", "Payment: charge card"], "service")], [node("e", ["Envio: agenda coleta", "Shipping: schedule pickup"], "service")]],
        [edge("o", "s", ["1. pedido criado", "1. order created"]), edge("s", "pg", ["2. reservado", "2. reserved"]), edge("pg", "e", ["3. pago", "3. paid"]), edge("pg", "s", ["falhou: libera", "failed: release"], { dashed: true })]),
      h(["Infraestrutura de apoio", "Supporting infrastructure"]),
      p(["Distribuir o sistema cria necessidades que um monolito não tem. A primeira é a **descoberta de serviços**: instâncias sobem e descem o tempo todo, então os endereços mudam. Em Kubernetes, o DNS interno e os objetos *Service* resolvem isso; fora dele, usam-se registros como Consul ou Eureka. O **API Gateway** é a porta de entrada única para clientes externos: faz autenticação, limite de requisições, roteamento e, às vezes, composição de respostas, evitando que o aplicativo móvel precise conhecer dezenas de endereços internos. Uma **malha de serviços** (*service mesh*, como Istio ou Linkerd) move para proxies ao lado de cada serviço a criptografia mútua (mTLS), retentativas e métricas, tirando esse código das aplicações.", "Distributing the system creates needs a monolith does not have. The first is **service discovery**: instances come and go all the time, so addresses change. In Kubernetes, internal DNS and *Service* objects solve this; outside it, registries such as Consul or Eureka are used. The **API Gateway** is the single entry point for external clients: it handles authentication, rate limiting, routing and sometimes response composition, sparing the mobile app from knowing dozens of internal addresses. A **service mesh** (such as Istio or Linkerd) moves mutual encryption (mTLS), retries and metrics to proxies next to each service, taking that code out of the applications."]),
      p(["Para resiliência, três defesas são quase obrigatórias em cada chamada de rede: **timeout** (nunca esperar para sempre), **retentativa com recuo exponencial e jitter** (só para operações idempotentes) e **circuit breaker** (parar de chamar um serviço que está falhando por um tempo, para não sobrecarregá-lo nem acumular requisições presas). Também se isola recursos com *bulkheads*, de modo que um serviço lento não consuma todas as threads do chamador.", "For resilience, three defenses are nearly mandatory on every network call: **timeout** (never wait forever), **retry with exponential backoff and jitter** (only for idempotent operations) and **circuit breaker** (stop calling a failing service for a while, so as not to overload it or pile up stuck requests). Resources are also isolated with *bulkheads*, so one slow service does not consume all of the caller's threads."]),
      code(`// resilient call to another service (TypeScript, Node 18+)
async function getPrice(sku: string): Promise<number> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 800);          // timeout
  try {
    const res = await fetch("http://catalog/prices/" + sku, { signal: ctrl.signal });
    if (!res.ok) throw new Error("catalog " + res.status);
    return (await res.json()).price;
  } finally {
    clearTimeout(timer);
  }
}

async function withRetry<T>(fn: () => Promise<T>, tries = 3): Promise<T> {
  for (let i = 0; ; i++) {
    try { return await fn(); }
    catch (err) {
      if (i + 1 >= tries) throw err;
      const wait = 100 * 2 ** i + Math.random() * 50;         // backoff + jitter
      await new Promise((r) => setTimeout(r, wait));
    }
  }
}`),
      h(["Observabilidade", "Observability"]),
      p(["Em um monolito, um stack trace conta a história inteira. Em microsserviços, uma única ação do usuário atravessa dez serviços, e sem instrumentação é impossível saber onde o tempo foi gasto ou onde a falha ocorreu. A observabilidade se apoia em três pilares. **Logs estruturados** (JSON, com campos como serviço, nível e ID de correlação). **Métricas** (taxa de requisições, erros, latência em percentis como p95 e p99, saturação). **Rastreamento distribuído** (*tracing*), em que cada requisição recebe um identificador de rastreio propagado em cabeçalhos (o padrão W3C Trace Context, usado pelo OpenTelemetry) e cada serviço registra seu trecho, permitindo ver a cascata completa em ferramentas como Jaeger ou Tempo.", "In a monolith, one stack trace tells the whole story. In microservices, a single user action crosses ten services, and without instrumentation it is impossible to know where time was spent or where the failure happened. Observability rests on three pillars. **Structured logs** (JSON, with fields such as service, level and correlation ID). **Metrics** (request rate, errors, latency at percentiles such as p95 and p99, saturation). **Distributed tracing**, in which each request receives a trace identifier propagated in headers (the W3C Trace Context standard, used by OpenTelemetry) and each service records its segment, letting you see the full waterfall in tools such as Jaeger or Tempo."]),
      h(["Migração gradual: strangler fig", "Gradual migration: strangler fig"]),
      p(["Reescrever um monolito do zero como microsserviços ('big bang') é uma das apostas mais arriscadas da engenharia de software: o projeto demora, o sistema antigo continua mudando e a entrega de valor para. O padrão **strangler fig** (figueira-estranguladora) evita isso. Coloca-se uma fachada (gateway ou proxy) na frente do monolito. Escolhe-se uma capacidade, de preferência pouco entrelaçada com o resto, constrói-se o novo serviço e redireciona-se para ele o tráfego correspondente, às vezes aos poucos (1%, 10%, 100%). O código antigo daquela parte é então removido. Repete-se, uma capacidade por vez, até o monolito encolher ao ponto de desaparecer ou de virar apenas mais um serviço.", "Rewriting a monolith from scratch as microservices ('big bang') is one of the riskiest bets in software engineering: the project drags on, the old system keeps changing and value delivery stops. The **strangler fig** pattern avoids this. A facade (gateway or proxy) is placed in front of the monolith. One capability is chosen, preferably one not tightly entangled with the rest, the new service is built and the corresponding traffic is redirected to it, sometimes gradually (1%, 10%, 100%). The old code for that part is then removed. Repeat, one capability at a time, until the monolith shrinks to nothing or becomes just another service."]),
      code(`# nginx as strangler facade: /billing goes to the new service,
# everything else still goes to the legacy monolith
upstream legacy  { server monolith.internal:8080; }
upstream billing { server billing.internal:8081; }

server {
  listen 443 ssl;
  location /api/billing/ { proxy_pass http://billing; }
  location /             { proxy_pass http://legacy; }
}`),
      h(["Vantagens e desvantagens", "Advantages and disadvantages"]),
      table([["Aspecto", "Aspect"], ["O que se ganha", "What you gain"], ["O que se paga", "What you pay"]],
        [["Deploy", "Deployment"], ["Independente e frequente, por equipe.", "Independent and frequent, per team."], ["Dezenas de pipelines; compatibilidade de contratos entre versões.", "Dozens of pipelines; contract compatibility between versions."]],
        [["Escala", "Scaling"], ["Seletiva: só o que precisa cresce.", "Selective: only what needs it grows."], ["Mais componentes para dimensionar e monitorar.", "More components to size and monitor."]],
        [["Falhas", "Failures"], ["Isolamento: um serviço cai sem derrubar tudo (se bem projetado).", "Isolation: one service fails without taking everything down (if well designed)."], ["Falhas parciais, em cascata e difíceis de reproduzir.", "Partial, cascading failures that are hard to reproduce."]],
        [["Tecnologia", "Technology"], ["Liberdade de escolha por serviço.", "Freedom of choice per service."], ["Diversidade custa: bibliotecas, padrões e conhecimento fragmentados.", "Diversity has a cost: libraries, standards and knowledge get fragmented."]],
        [["Dados", "Data"], ["Autonomia de esquema e de tecnologia de armazenamento.", "Autonomy of schema and storage technology."], ["Sem JOIN nem transação global; sagas e consistência eventual.", "No JOIN or global transaction; sagas and eventual consistency."]],
        [["Equipe", "Team"], ["Autonomia e responsabilidade clara.", "Autonomy and clear responsibility."], ["Exige maturidade de DevOps, plataforma e cultura de operação.", "Requires DevOps maturity, a platform and an operations culture."]],
      ),
      h(["Anti-padrões comuns", "Common anti-patterns"]),
      ul(
        ["**Monolito distribuído**: serviços que precisam ser publicados juntos ou que compartilham o banco. Custo total da rede, nenhum benefício de independência.", "**Distributed monolith**: services that must be released together or that share the database. Full network cost, no independence benefit."],
        ["**Nano-serviços**: granularidade tão fina que cada pedido do usuário vira dezenas de chamadas e a lógica fica dispersa.", "**Nano-services**: granularity so fine that each user request becomes dozens of calls and logic gets scattered."],
        ["**Cadeias síncronas profundas**: A chama B, que chama C, que chama D; a latência soma e a disponibilidade multiplica.", "**Deep synchronous chains**: A calls B, which calls C, which calls D; latency adds up and availability multiplies down."],
        ["**Banco compartilhado**: o esquema se torna um contrato oculto e impede mudanças locais.", "**Shared database**: the schema becomes a hidden contract and blocks local changes."],
        ["**Biblioteca compartilhada com regra de negócio**: força todos a atualizar juntos e recria o acoplamento do monolito.", "**Shared library with business rules**: forces everyone to upgrade together and recreates monolith coupling."],
        ["**Começar sem automação**: microsserviços sem CI/CD, contêineres, monitoramento e logs centralizados viram um pesadelo manual.", "**Starting without automation**: microservices without CI/CD, containers, monitoring and centralized logs become a manual nightmare."],
      ),
      h(["Casos reais", "Real-world cases"]),
      p(["A Netflix é o exemplo mais citado: migrou de um monolito em data center próprio para centenas de serviços na nuvem, e criou bibliotecas hoje conhecidas, como o Hystrix (circuit breaker) e o Eureka (descoberta de serviços). A Amazon relatou que equipes pequenas, donas de serviços com APIs bem definidas, são parte central do seu modo de operar. O ponto em comum não é a tecnologia, e sim o investimento em plataforma interna, automação e cultura de responsabilidade por produção. Empresas sem esse investimento raramente colhem os mesmos resultados.", "Netflix is the most cited example: it migrated from a monolith in its own data center to hundreds of services in the cloud, and created now-known libraries such as Hystrix (circuit breaker) and Eureka (service discovery). Amazon has reported that small teams owning services with well-defined APIs are central to how it operates. What they share is not the technology but the investment in internal platform, automation and a culture of production ownership. Companies without that investment rarely reap the same results."]),
      h(["Resumo", "Summary"]),
      ul(
        ["Microsserviços são serviços pequenos, de negócio, com deploy e dados independentes.", "Microservices are small, business-oriented services with independent deploys and data."],
        ["As fronteiras seguem contextos de negócio (DDD), não camadas técnicas.", "Boundaries follow business contexts (DDD), not technical layers."],
        ["Prefira eventos quando o efeito pode esperar e chamadas síncronas quando o usuário espera a resposta.", "Prefer events when the effect can wait and synchronous calls when the user waits for the answer."],
        ["Sem transação global: use sagas e aceite consistência eventual.", "No global transaction: use sagas and accept eventual consistency."],
        ["Exigem gateway, descoberta, resiliência e observabilidade desde o início.", "They demand a gateway, discovery, resilience and observability from the start."],
        ["Migre com strangler fig, nunca com reescrita total.", "Migrate with strangler fig, never with a full rewrite."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Qual o tamanho certo de um microsserviço?** Não é medido em linhas de código: é o que uma equipe pequena consegue entender, publicar e operar sozinha, em torno de uma capacidade de negócio.", "**What is the right size for a microservice?** It is not measured in lines of code: it is what a small team can understand, ship and operate alone, around a business capability."],
        ["**Posso usar um banco compartilhado por praticidade?** Pode, mas você perde a independência de deploy e cria um monolito distribuído. Prefira que cada serviço exponha uma API.", "**Can I use a shared database for convenience?** You can, but you lose deploy independence and create a distributed monolith. Prefer each service exposing an API."],
        ["**Microsserviços são mais rápidos?** Em geral não: cada salto de rede soma latência. O ganho é de escala e de autonomia, não de velocidade por requisição.", "**Are microservices faster?** Generally not: each network hop adds latency. The gain is in scale and autonomy, not per-request speed."],
        ["**Preciso de Kubernetes?** Não é obrigatório, mas orquestração de contêineres resolve descoberta, escala e deploy de modo padronizado; sem algo equivalente, a operação pesa.", "**Do I need Kubernetes?** Not mandatory, but container orchestration solves discovery, scaling and deployment in a standard way; without something equivalent, operations get heavy."],
      ),
      tip(["Se dois serviços sempre mudam juntos ou compartilham o mesmo banco, você tem um **monolito distribuído**: todo o custo da rede e nenhum dos benefícios. O objetivo não é ter muitos serviços, e sim poder mudar uma parte do sistema sem pedir licença ao resto.", "If two services always change together or share the same database, you have a **distributed monolith**: all the network cost and none of the benefits. The goal is not to have many services but to be able to change one part of the system without asking the rest for permission."]),
    ] },

  { id: "monolito-vs-microsservicos", section: "estilos", level: 1, icon: "compare_arrows", minutes: 12,
    title: ["Monolito ou microsserviços?", "Monolith or microservices?"],
    summary: ["Uma comparação direta, quando migrar e o meio-termo do monolito modular.", "A direct comparison, when to migrate and the middle ground of the modular monolith."],
    body: [
      p(["Poucas decisões de arquitetura geram tanto debate quanto esta. De um lado, a ideia de que microsserviços são o destino natural de todo sistema sério; de outro, a reação de quem viu equipes pequenas afundarem em complexidade operacional. A verdade é menos dramática: são **duas ferramentas com custos e benefícios diferentes**, e a escolha certa depende do tamanho da equipe, do estágio do produto, da maturidade de operação e da forma do problema. Este artigo coloca os dois estilos lado a lado, descreve sinais de que é hora de mudar, apresenta o meio-termo do monolito modular e termina com um roteiro de decisão.", "Few architecture decisions generate as much debate as this one. On one side, the idea that microservices are the natural destination of every serious system; on the other, the reaction of people who saw small teams sink into operational complexity. The truth is less dramatic: they are **two tools with different costs and benefits**, and the right choice depends on team size, product stage, operations maturity and the shape of the problem. This article puts the two styles side by side, describes signs that it is time to change, presents the middle ground of the modular monolith and ends with a decision guide."]),
      p(["Uma pergunta ajuda a orientar tudo o que vem a seguir: **qual problema eu tenho hoje?** Microsserviços resolvem problemas de **organização e escala** (muitas equipes, deploys que se bloqueiam, cargas muito desiguais). Se esse não é o seu problema, a solução vai custar mais do que entrega.", "One question helps guide everything that follows: **which problem do I have today?** Microservices solve **organization and scale** problems (many teams, blocking deploys, very uneven loads). If that is not your problem, the solution will cost more than it delivers."]),
      h(["Comparação lado a lado", "Side-by-side comparison"]),
      table([["Critério", "Criterion"], ["Monolito", "Monolith"], ["Microsserviços", "Microservices"]],
        [["Complexidade do código", "Code complexity"], ["Baixa a média; tudo em um lugar, mas pode emaranhar sem disciplina.", "Low to medium; everything in one place, but can tangle without discipline."], ["Cada serviço é simples; o sistema como um todo é complexo.", "Each service is simple; the system as a whole is complex."]],
        [["Complexidade operacional", "Operational complexity"], ["Baixa: um artefato, um pipeline, um painel.", "Low: one artifact, one pipeline, one dashboard."], ["Alta: muitos pipelines, descoberta, gateway, observabilidade distribuída.", "High: many pipelines, discovery, gateway, distributed observability."]],
        [["Deploy", "Deployment"], ["Único e acoplado; uma mudança pequena publica tudo.", "Single and coupled; a small change ships everything."], ["Independente por serviço; vários por dia.", "Independent per service; several per day."]],
        [["Escala", "Scaling"], ["Replica a aplicação inteira.", "Replicates the whole application."], ["Escala cada serviço conforme a demanda.", "Scales each service according to demand."]],
        [["Consistência", "Consistency"], ["Transações ACID simples.", "Simple ACID transactions."], ["Consistência eventual, sagas, idempotência.", "Eventual consistency, sagas, idempotency."]],
        [["Latência interna", "Internal latency"], ["Nanossegundos por chamada.", "Nanoseconds per call."], ["Milissegundos por salto, com risco de falha.", "Milliseconds per hop, with risk of failure."]],
        [["Isolamento de falhas", "Fault isolation"], ["Um domínio de falha só.", "A single failure domain."], ["Falhas contidas, se houver timeouts e circuit breakers.", "Contained failures, if there are timeouts and circuit breakers."]],
        [["Tecnologia", "Technology"], ["Uma pilha para todos.", "One stack for everyone."], ["Livre por serviço, ao custo de fragmentação.", "Free per service, at the cost of fragmentation."]],
        [["Testes", "Testing"], ["Integração simples, no mesmo processo.", "Simple integration, in the same process."], ["Exigem testes de contrato e ambientes integrados.", "Require contract tests and integrated environments."]],
        [["Equipe ideal", "Ideal team"], ["Uma equipe ou poucas, trabalhando de perto.", "One team or a few, working closely."], ["Muitas equipes autônomas, com plataforma interna.", "Many autonomous teams, with an internal platform."]],
        [["Custo inicial", "Initial cost"], ["Baixo: começa-se a entregar no primeiro dia.", "Low: you start delivering on day one."], ["Alto: é preciso montar a plataforma antes de colher o benefício.", "High: the platform must be built before reaping the benefit."]],
      ),
      h(["Como o custo muda com o tamanho", "How cost changes with size"]),
      p(["A relação entre os estilos muda com a escala da organização. Com poucas pessoas, o monolito é muito mais barato: nenhum custo fixo de plataforma, mudanças atravessam módulos sem cerimônia. À medida que o número de equipes cresce, o custo de coordenação do monolito sobe (conflitos, builds longos, deploys que se bloqueiam), enquanto o custo fixo dos microsserviços fica diluído por mais equipes. Existe um ponto de cruzamento, e ele depende mais de pessoas e de processo do que de tráfego de usuários. Uma equipe de dez pessoas raramente o atinge; uma de duzentas quase sempre o ultrapassou.", "The relationship between the styles changes with organizational scale. With few people, the monolith is far cheaper: no fixed platform cost, changes cross modules without ceremony. As the number of teams grows, the monolith's coordination cost climbs (conflicts, long builds, blocking deploys), while the fixed cost of microservices is spread over more teams. There is a crossover point, and it depends more on people and process than on user traffic. A ten-person team rarely reaches it; a two-hundred-person organization has almost always passed it."]),
      p(["Essa observação costuma ser resumida pela **Lei de Conway**: sistemas tendem a refletir a estrutura de comunicação das organizações que os constroem. Microsserviços funcionam melhor quando as fronteiras entre serviços coincidem com as fronteiras entre equipes; dividir o sistema sem dividir a organização gera serviços acoplados por reuniões em vez de por código, o que não é melhora.", "This observation is usually summarized by **Conway's Law**: systems tend to mirror the communication structure of the organizations that build them. Microservices work best when service boundaries coincide with team boundaries; splitting the system without splitting the organization yields services coupled by meetings instead of code, which is no improvement."]),
      h(["Sinais reais e sinais falsos para migrar", "Real and false signs for migrating"]),
      p(["Sinais reais de que o monolito chegou ao limite:", "Real signs that the monolith has reached its limit:"]),
      ul(
        ["Times se atrapalham: conflitos constantes, deploys que esperam uns pelos outros, janelas de publicação disputadas, builds de dezenas de minutos.", "Teams get in each other's way: constant conflicts, deploys waiting on one another, contested release windows, builds taking tens of minutes."],
        ["Uma parte do sistema tem necessidade de escala ou de tecnologia muito diferente do resto (processamento de vídeo, busca, inferência de modelos).", "One part of the system has scale or technology needs very different from the rest (video processing, search, model inference)."],
        ["Um módulo instável derruba o sistema todo e precisa de isolamento de falhas.", "An unstable module takes the whole system down and needs fault isolation."],
        ["Requisitos regulatórios ou de segurança exigem separar um conjunto de dados (pagamentos, dados de saúde) com acesso restrito.", "Regulatory or security requirements demand isolating a data set (payments, health data) with restricted access."],
        ["A atualização de uma dependência central (framework, linguagem) é tão arriscada que ninguém a faz há anos.", "Upgrading a core dependency (framework, language) is so risky that nobody has done it in years."],
      ),
      p(["Sinais falsos, motivos que parecem bons e não são:", "False signs, reasons that look good but are not:"]),
      ul(
        ["'É moderno' ou 'o currículo da equipe melhora'.", "'It is modern' or 'it improves the team's résumés'."],
        ["'A empresa X faz assim': ela tem milhares de engenheiros e uma plataforma que você não tem.", "'Company X does it': it has thousands of engineers and a platform you do not have."],
        ["'Vai escalar um dia': otimizar para uma escala hipotética paga o custo agora por um benefício que talvez nunca chegue.", "'It will scale someday': optimizing for a hypothetical scale pays the cost now for a benefit that may never arrive."],
        ["'O código está uma bagunça': dividir uma bagunça em serviços cria uma bagunça distribuída, mais difícil de consertar.", "'The code is a mess': splitting a mess into services creates a distributed mess, harder to fix."],
      ),
      h(["O meio-termo: monolito modular", "The middle ground: the modular monolith"]),
      p(["Entre os dois extremos existe uma opção que resolve boa parte da dor sem pagar o preço inteiro. Um **monolito modular** é uma única aplicação dividida internamente em módulos de negócio com fronteiras rígidas. Cada módulo expõe uma interface pública pequena, esconde suas tabelas e não acessa o banco dos outros. As chamadas entre módulos passam por essas interfaces, e é possível reforçar a regra com ferramentas que falham o build ao detectar uma dependência proibida. Mantêm-se um deploy, uma transação e um pipeline; ganha-se a clareza de ownership e a possibilidade de extrair um módulo no futuro com custo baixo, porque a costura já existe.", "Between the two extremes there is an option that solves much of the pain without paying the whole price. A **modular monolith** is a single application divided internally into business modules with rigid boundaries. Each module exposes a small public interface, hides its tables and does not touch the others' database. Calls between modules go through those interfaces, and the rule can be enforced by tools that fail the build when a forbidden dependency is detected. You keep one deploy, one transaction and one pipeline; you gain clear ownership and the ability to extract a module later at low cost, because the seam already exists."]),
      fig(["O espectro: do emaranhado à divisão total", "The spectrum: from tangled to fully split"],
        [[node("ball", ["Monolito sem fronteiras", "Monolith without boundaries"], "ext")], [node("mod", ["Monolito modular", "Modular monolith"], "service")], [node("some", ["Monolito + poucos serviços extraídos", "Monolith + a few extracted services"], "service")], [node("micro", ["Microsserviços completos", "Full microservices"], "service")]],
        [edge("ball", "mod", ["impor fronteiras", "enforce boundaries"]), edge("mod", "some", ["extrair o que justifica", "extract what is justified"]), edge("some", "micro", ["só se a dor continuar", "only if pain persists"], { dashed: true })]),
      p(["Esse caminho incremental é, na maioria das vezes, o mais seguro. Cada passo é reversível e é motivado por um problema concreto que o passo anterior não resolveu. Muitas organizações descobrem que ficam muito bem em 'monolito mais três ou quatro serviços' e nunca precisam ir além.", "This incremental path is, most of the time, the safest. Each step is reversible and motivated by a concrete problem the previous step did not solve. Many organizations find they are perfectly fine at 'monolith plus three or four services' and never need to go further."]),
      h(["Fluxograma de decisão", "Decision flowchart"]),
      p(["Use as perguntas abaixo, em ordem. Elas não substituem análise, mas evitam as decisões por moda.", "Use the questions below, in order. They do not replace analysis, but they avoid decisions by fashion."]),
      fig(["Roteiro de decisão", "Decision guide"],
        [[node("q1", ["Mais de ~5 equipes que se bloqueiam?", "More than ~5 teams blocking each other?"], "client")], [node("q2", ["Partes com escala ou tecnologia muito diferentes?", "Parts with very different scale or technology?"], "client")], [node("q3", ["Há plataforma, CI/CD e observabilidade?", "Is there a platform, CI/CD and observability?"], "client")], [node("mono", ["Monolito modular", "Modular monolith"], "data"), node("ms", ["Extrair serviços, um por vez", "Extract services, one at a time"], "service")]],
        [edge("q1", "q2", ["sim", "yes"]), edge("q1", "mono", ["não", "no"], { dashed: true }), edge("q2", "q3", ["sim", "yes"]), edge("q3", "ms", ["sim", "yes"]), edge("q3", "mono", ["não: construir antes", "no: build first"], { dashed: true })]),
      h(["Como migrar sem big bang", "How to migrate without a big bang"]),
      p(["Quando a decisão é migrar, o padrão **strangler fig** é o mais usado. Coloque uma fachada (gateway ou proxy reverso) na frente do monolito e comece a extrair uma capacidade de cada vez, de preferência a mais independente: notificações, geração de relatórios, upload e processamento de mídia costumam ser bons primeiros candidatos, porque têm poucos vínculos de dados. O tráfego é redirecionado aos poucos, o código antigo correspondente é removido e o monolito encolhe. Os dados são o ponto mais delicado: durante a transição, o novo serviço pode ler do banco antigo por meio de uma visão ou de replicação, até assumir a posse da tabela por completo.", "When the decision is to migrate, the **strangler fig** pattern is the most used. Put a facade (gateway or reverse proxy) in front of the monolith and extract one capability at a time, preferably the most independent: notifications, report generation, media upload and processing are often good first candidates because they have few data ties. Traffic is redirected gradually, the corresponding old code is removed and the monolith shrinks. Data is the most delicate point: during the transition the new service may read from the old database through a view or replication, until it takes full ownership of the table."]),
      ul(
        ["**Antes de extrair**: torne o módulo independente dentro do monolito (interface pública, tabelas próprias, sem JOIN para fora).", "**Before extracting**: make the module independent inside the monolith (public interface, own tables, no JOINs outside)."],
        ["**Durante**: proxy na frente, rollout gradual, comparação de respostas entre o código velho e o novo quando possível.", "**During**: proxy in front, gradual rollout, comparing responses between old and new code when possible."],
        ["**Depois**: migrar os dados, remover o código antigo e só então considerar o próximo módulo.", "**After**: migrate the data, remove the old code and only then consider the next module."],
      ),
      h(["Erros comuns de decisão", "Common decision mistakes"]),
      ul(
        ["**Começar com microsserviços em um produto novo**: as fronteiras ainda são desconhecidas, e cada erro vira uma migração entre serviços.", "**Starting with microservices on a new product**: boundaries are still unknown, and each mistake becomes a migration between services."],
        ["**Dividir por camada** (serviço de dados, serviço de regras), e não por capacidade de negócio.", "**Splitting by layer** (data service, rules service) instead of by business capability."],
        ["**Subestimar a operação**: sem CI/CD, monitoramento e logs centralizados, cada serviço novo piora o dia a dia.", "**Underestimating operations**: without CI/CD, monitoring and centralized logs, every new service worsens day-to-day work."],
        ["**Reescrever tudo de uma vez**: o sistema antigo continua evoluindo e a reescrita nunca o alcança.", "**Rewriting everything at once**: the old system keeps evolving and the rewrite never catches up."],
        ["**Ignorar a organização**: serviços sem donos claros viram terreno de ninguém.", "**Ignoring the organization**: services without clear owners become no-one's land."],
      ),
      h(["Resumo", "Summary"]),
      ul(
        ["Nenhum estilo é melhor em abstrato: compare pelo problema que você tem.", "Neither style is better in the abstract: compare by the problem you have."],
        ["Monolito: simples, barato, transações ACID; limitado por deploy acoplado e escala uniforme.", "Monolith: simple, cheap, ACID transactions; limited by coupled deploys and uniform scaling."],
        ["Microsserviços: autonomia e escala seletiva; exigem plataforma e aceitam consistência eventual.", "Microservices: autonomy and selective scaling; require a platform and accept eventual consistency."],
        ["O monolito modular é o melhor ponto de partida e muitas vezes o ponto de chegada.", "The modular monolith is the best starting point and often the destination."],
        ["Migre com strangler fig, um módulo por vez, motivado por dor real.", "Migrate with strangler fig, one module at a time, motivated by real pain."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Quantas pessoas justificam microsserviços?** Não há número mágico. Em geral, os benefícios aparecem quando várias equipes precisam publicar de modo independente; com uma equipe só, raramente compensam.", "**How many people justify microservices?** There is no magic number. Generally the benefits appear when several teams must ship independently; with a single team they rarely pay off."],
        ["**Dá para voltar de microsserviços para monolito?** Dá, e algumas empresas já o fizeram ao perceber que o custo superava o ganho. É mais fácil quando os serviços ainda são poucos e o banco não foi muito espalhado.", "**Can you go back from microservices to a monolith?** Yes, and some companies have, upon realizing the cost exceeded the gain. It is easier when the services are still few and the data is not too scattered."],
        ["**Monolito modular precisa de ferramenta especial?** Basta convenção e verificação automática de dependências entre módulos no build.", "**Does a modular monolith need special tooling?** Convention plus automatic checking of module dependencies in the build is enough."],
        ["**E o desempenho?** O monolito costuma ser mais rápido por requisição, pois evita saltos de rede. Microsserviços ganham em escalar partes e em isolar falhas.", "**What about performance?** The monolith is usually faster per request, as it avoids network hops. Microservices win at scaling parts and isolating failures."],
      ),
      tip(["Regra prática: separe um serviço quando a dor de **não** separar for maior que a dor de operar mais um serviço. Antes disso, um módulo bem isolado resolve.", "Rule of thumb: split out a service when the pain of **not** splitting is greater than the pain of running one more service. Before that, a well-isolated module does the job."]),
    ] },

  { id: "arquitetura-orientada-a-eventos", section: "estilos", level: 1, icon: "bolt", minutes: 14,
    title: ["Arquitetura orientada a eventos", "Event-driven architecture"],
    summary: ["Serviços que reagem a fatos que aconteceram, em vez de se chamarem uns aos outros.", "Services that react to facts that happened instead of calling one another."],
    body: [
      p(["Numa arquitetura tradicional, o serviço de pedidos, ao receber uma compra, chama o de pagamento, depois o de estoque, depois o de e-mail, depois o de análise. Cada chamada é um acoplamento: o serviço de pedidos precisa conhecer todos os destinatários, esperar cada resposta e sofrer se algum estiver lento. Adicionar um novo interessado, como um programa de fidelidade, exige mexer no serviço de pedidos. A **arquitetura orientada a eventos** (*event-driven architecture*, EDA) inverte essa lógica: o serviço de pedidos apenas **anuncia um fato** ('pedido criado') e quem se interessa reage por conta própria.", "In a traditional architecture, the orders service, on receiving a purchase, calls payment, then stock, then email, then analytics. Each call is a coupling: the orders service must know all the recipients, wait for each response and suffer if any is slow. Adding a new interested party, such as a loyalty program, requires changing the orders service. **Event-driven architecture** (EDA) inverts this logic: the orders service merely **announces a fact** ('order created') and whoever is interested reacts on its own."]),
      p(["O resultado é um sistema em que as partes se conhecem pouco, evoluem separadamente e continuam funcionando quando uma delas está lenta ou fora do ar. Em troca, o comportamento do conjunto deixa de estar escrito em um único lugar: ele emerge das reações. Dominar essa arquitetura significa entender bem os papéis, as garantias do broker e os cuidados que o modelo assíncrono impõe.", "The result is a system whose parts know little about each other, evolve separately and keep working when one of them is slow or down. In exchange, the behavior of the whole is no longer written in a single place: it emerges from the reactions. Mastering this architecture means understanding the roles, the broker's guarantees and the care the asynchronous model imposes."]),
      h(["Conceitos fundamentais", "Core concepts"]),
      ul(
        ["**Evento**: o registro imutável de algo que já aconteceu, nomeado no passado ('pedido.criado', 'pagamento.aprovado'). Não pode ser desfeito; só compensado por outro evento ('pagamento.estornado').", "**Event**: the immutable record of something that already happened, named in the past ('order.created', 'payment.approved'). It cannot be undone; only compensated by another event ('payment.refunded')."],
        ["**Produtor** (*producer* ou *publisher*): quem detecta o fato e o publica, sem saber quem vai reagir.", "**Producer** (or *publisher*): whoever detects the fact and publishes it, without knowing who will react."],
        ["**Broker**: o intermediário durável (Apache Kafka, RabbitMQ, AWS SNS/SQS, Google Pub/Sub, Azure Service Bus) que recebe, guarda e entrega os eventos.", "**Broker**: the durable intermediary (Apache Kafka, RabbitMQ, AWS SNS/SQS, Google Pub/Sub, Azure Service Bus) that receives, stores and delivers events."],
        ["**Consumidor**: quem reage ao evento, no seu próprio ritmo, sem que o produtor saiba que ele existe.", "**Consumer**: whoever reacts to the event, at its own pace, without the producer knowing it exists."],
        ["**Tópico** ou **canal**: o nome sob o qual eventos do mesmo tipo são agrupados.", "**Topic** or **channel**: the name under which events of the same kind are grouped."],
      ),
      h(["Eventos, comandos e consultas", "Events, commands and queries"]),
      p(["Uma confusão frequente é tratar qualquer mensagem como evento. Convém distinguir três tipos. Um **comando** é uma ordem dirigida a um destinatário específico, no imperativo ('cobrar pedido 42'), e pode ser recusado. Um **evento** é um fato no passado, dirigido a ninguém em particular ('pedido 42 foi criado'), e não pode ser recusado, só ignorado. Uma **consulta** pede um dado e espera a resposta. Misturar os conceitos produz sistemas em que o 'evento' é, na prática, uma chamada remota disfarçada, com o produtor esperando que alguém faça algo específico.", "A frequent confusion is treating any message as an event. It helps to distinguish three kinds. A **command** is an order addressed to a specific recipient, in the imperative ('charge order 42'), and can be refused. An **event** is a fact in the past, addressed to no one in particular ('order 42 was created'), and cannot be refused, only ignored. A **query** asks for data and awaits the answer. Mixing the concepts yields systems in which the 'event' is in practice a disguised remote call, with the producer expecting someone to do something specific."]),
      table([["Tipo", "Kind"], ["Tempo verbal", "Tense"], ["Destinatário", "Recipient"], ["Exemplo", "Example"]],
        [["Comando", "Command"], ["Imperativo", "Imperative"], ["Um serviço específico", "One specific service"], ["ChargePayment", "ChargePayment"]],
        [["Evento", "Event"], ["Passado", "Past"], ["Qualquer interessado", "Any interested party"], ["OrderCreated", "OrderCreated"]],
        [["Consulta", "Query"], ["Pergunta", "Question"], ["Um serviço específico", "One specific service"], ["GetOrderStatus", "GetOrderStatus"]],
      ),
      h(["Exemplo completo: e-commerce", "Complete example: e-commerce"]),
      p(["Veja uma compra do início ao fim. O cliente finaliza o pedido; o serviço de Pedidos grava o pedido no seu banco e publica o evento **pedido.criado**. O serviço de Pagamento, que assina esse tópico, tenta cobrar o cartão e publica **pagamento.aprovado** (ou **pagamento.recusado**). O serviço de Estoque, também assinante de pedido.criado, reserva os itens e publica **estoque.reservado**. Quando o pagamento é aprovado, o serviço de Envio gera a etiqueta e agenda a coleta. Em paralelo, Notificações envia o e-mail de confirmação e Analytics atualiza os painéis, sem que o serviço de Pedidos tenha sido modificado para isso.", "Follow a purchase from start to finish. The customer finalizes the order; the Orders service writes the order to its database and publishes the event **order.created**. The Payment service, which subscribes to that topic, tries to charge the card and publishes **payment.approved** (or **payment.declined**). The Stock service, also a subscriber of order.created, reserves the items and publishes **stock.reserved**. When payment is approved, the Shipping service generates the label and schedules pickup. In parallel, Notifications sends the confirmation email and Analytics updates dashboards, without the Orders service having been modified for any of this."]),
      fig(["Fluxo de eventos de uma compra", "Event flow of a purchase"],
        [[node("ord", ["Pedidos", "Orders"], "service")], [node("br", ["Broker de eventos", "Event broker"], "queue")], [node("pay", ["Pagamento", "Payment"], "service"), node("stk", ["Estoque", "Stock"], "service"), node("not", ["Notificações", "Notifications"], "service"), node("ana", "Analytics", "service")], [node("ship", ["Envio", "Shipping"], "service")]],
        [edge("ord", "br", ["pedido.criado", "order.created"]), edge("br", "pay"), edge("br", "stk"), edge("br", "not"), edge("br", "ana"), edge("pay", "ship", ["pagamento.aprovado", "payment.approved"], { dashed: true })]),
      p(["Sem eventos, o serviço de Pedidos teria que chamar cada um em sequência, conhecer todos e falhar se um deles falhasse. Para adicionar um novo interessado (um programa de fidelidade que dá pontos a cada compra), basta que ele assine o tópico: o serviço de Pedidos não muda, não é reimplantado e nem sabe que a novidade existe.", "Without events, the Orders service would have to call each in sequence, know all of them and fail if one failed. To add a new interested party (a loyalty program that awards points on every purchase), it only needs to subscribe to the topic: the Orders service does not change, is not redeployed and does not even know the newcomer exists."]),
      h(["O problema da gravação dupla e o padrão outbox", "The dual-write problem and the outbox pattern"]),
      p(["Um defeito sutil e comum: o serviço grava o pedido no banco **e** publica o evento no broker. São dois sistemas e nenhuma transação os cobre. Se o banco confirma e o broker falha, o pedido existe, mas ninguém soube. Se a ordem for invertida, o evento circula para um pedido que não existe. A solução clássica é o **transactional outbox**: na mesma transação do banco, o serviço grava o pedido e também uma linha em uma tabela de saída (*outbox*) com o evento. Um processo separado lê essa tabela e publica no broker, marcando as linhas como enviadas. Como a publicação pode se repetir, os consumidores precisam ser idempotentes. Ferramentas de captura de mudanças (*change data capture*, como o Debezium) automatizam a leitura.", "A subtle and common defect: the service writes the order to the database **and** publishes the event to the broker. These are two systems and no transaction covers both. If the database commits and the broker fails, the order exists but nobody learned of it. If the order is reversed, the event circulates for an order that does not exist. The classic solution is the **transactional outbox**: in the same database transaction, the service writes the order and also a row in an outbox table holding the event. A separate process reads this table and publishes to the broker, marking rows as sent. Since publishing may repeat, consumers must be idempotent. Change data capture tools (such as Debezium) automate the reading."]),
      code(`-- one local transaction: business data + event to publish
BEGIN;
  INSERT INTO orders (id, customer_id, total_cents, status)
  VALUES ('ord_42', 'cus_7', 15990, 'CREATED');

  INSERT INTO outbox (id, topic, key, payload, created_at)
  VALUES ('evt_981', 'orders.created', 'ord_42',
          '{"orderId":"ord_42","totalCents":15990}', now());
COMMIT;
-- a relay process: SELECT unsent rows -> publish -> mark as sent`),
      h(["Garantias de entrega e ordenação", "Delivery guarantees and ordering"]),
      p(["Todo broker oferece alguma garantia de entrega, e escolher a certa é uma decisão de projeto. Em **no máximo uma vez** (*at-most-once*), a mensagem pode ser perdida mas nunca duplicada: serve para dados descartáveis, como telemetria. Em **ao menos uma vez** (*at-least-once*), nada se perde, mas pode haver duplicatas, pois o broker reenvia se não receber a confirmação: é o padrão mais comum. Em **exatamente uma vez** (*exactly-once*), o efeito acontece uma única vez, mas isso só se obtém dentro de limites (por exemplo, transações do Kafka entre tópicos do próprio Kafka) e tem custo; fora desses limites, o que se faz é combinar at-least-once com um consumidor idempotente.", "Every broker offers some delivery guarantee, and choosing the right one is a design decision. With **at-most-once**, the message may be lost but never duplicated: suitable for disposable data such as telemetry. With **at-least-once**, nothing is lost but duplicates may occur, as the broker resends if it receives no acknowledgment: the most common default. With **exactly-once**, the effect happens a single time, but this is only achievable within limits (for example, Kafka transactions between Kafka's own topics) and has a cost; outside those limits, what you do is combine at-least-once with an idempotent consumer."]),
      p(["Sobre a **ordem**, a garantia é parcial: o Kafka preserva a ordem dentro de uma partição, e o que decide a partição é a **chave** da mensagem. Se todos os eventos de um mesmo pedido usam o ID do pedido como chave, eles vão para a mesma partição e são consumidos na ordem em que foram gravados. Entre partições diferentes não existe ordem global. Filas padrão do SQS também não garantem ordem, ao contrário das filas FIFO. Projete os consumidores para tolerar eventos fora de ordem sempre que possível, por exemplo comparando um número de versão antes de aplicar uma atualização.", "On **ordering**, the guarantee is partial: Kafka preserves order within a partition, and what decides the partition is the message **key**. If all events of one order use the order ID as key, they go to the same partition and are consumed in the order they were written. Across different partitions there is no global order. Standard SQS queues also do not guarantee order, unlike FIFO queues. Design consumers to tolerate out-of-order events whenever possible, for example by comparing a version number before applying an update."]),
      h(["Idempotência no consumidor", "Idempotency in the consumer"]),
      p(["Como a entrega ao-menos-uma-vez pode repetir eventos, processar o mesmo evento duas vezes não pode gerar duas cobranças nem dois e-mails. A técnica mais simples é guardar o identificador de cada evento processado e ignorar repetições, de preferência dentro da mesma transação que aplica o efeito.", "Since at-least-once delivery may repeat events, processing the same event twice must not generate two charges or two emails. The simplest technique is to store the identifier of each processed event and ignore repeats, preferably inside the same transaction that applies the effect."]),
      code(`// idempotent consumer (TypeScript, pseudo-DB API)
interface OrderCreated {
  eventId: string;     // unique per event, assigned by the producer
  orderId: string;
  totalCents: number;
  version: number;     // schema version
}

async function onOrderCreated(evt: OrderCreated, db: Db) {
  await db.transaction(async (tx) => {
    const seen = await tx.query("SELECT 1 FROM processed_events WHERE id = $1", [evt.eventId]);
    if (seen.rowCount > 0) return;                       // duplicate: ignore
    await tx.query("INSERT INTO payments (order_id, amount_cents, status) VALUES ($1, $2, 'PENDING')",
                   [evt.orderId, evt.totalCents]);
    await tx.query("INSERT INTO processed_events (id) VALUES ($1)", [evt.eventId]);
  });
}`),
      h(["Esquema e evolução dos eventos", "Event schema and evolution"]),
      p(["O formato do evento é um contrato entre equipes que podem nunca conversar. Defina-o de modo explícito, com formato binário compacto e esquema (Avro ou Protobuf) ou JSON com JSON Schema, e mantenha um **schema registry** (como o Confluent Schema Registry) que valida a compatibilidade antes da publicação. As regras de evolução seguras: adicionar campos opcionais é compatível; remover ou renomear campos, mudar tipos ou mudar o significado quebra consumidores. Quando uma quebra é inevitável, publique em um novo tópico ou versão e mantenha os dois por um período. Inclua em todo evento um identificador único, o instante da ocorrência, o tipo, a versão do esquema e um ID de correlação para rastreamento.", "The event format is a contract between teams that may never talk. Define it explicitly, with a compact binary format and schema (Avro or Protobuf) or JSON with JSON Schema, and keep a **schema registry** (such as the Confluent Schema Registry) that validates compatibility before publishing. The safe evolution rules: adding optional fields is compatible; removing or renaming fields, changing types or changing meaning breaks consumers. When a break is unavoidable, publish to a new topic or version and keep both for a while. Include in every event a unique identifier, the time of occurrence, the type, the schema version and a correlation ID for tracing."]),
      code(`{
  "eventId": "evt_981",
  "type": "order.created",
  "schemaVersion": 2,
  "occurredAt": "2026-03-14T12:00:00Z",
  "correlationId": "req_7f3a",
  "data": { "orderId": "ord_42", "customerId": "cus_7", "totalCents": 15990 }
}`),
      h(["Padrões relacionados", "Related patterns"]),
      ul(
        ["**Notificação de evento**: o evento carrega só o ID, e o consumidor busca os detalhes. Leve, mas gera chamadas de volta ao produtor.", "**Event notification**: the event carries just the ID, and the consumer fetches the details. Light, but generates calls back to the producer."],
        ["**Transferência de estado por evento**: o evento carrega os dados necessários, e o consumidor mantém sua própria cópia. Mais desacoplado, com eventos maiores.", "**Event-carried state transfer**: the event carries the needed data, and the consumer keeps its own copy. More decoupled, with larger events."],
        ["**Event sourcing**: o estado de uma entidade é a soma dos seus eventos, guardados como fonte da verdade. Dá histórico completo e auditoria, mas aumenta a complexidade de consultas e de evolução de esquema.", "**Event sourcing**: an entity's state is the sum of its events, stored as the source of truth. It gives full history and auditing, but increases the complexity of queries and schema evolution."],
        ["**CQRS**: separar o modelo de escrita do de leitura, com as leituras alimentadas por eventos. Combina bem com EDA.", "**CQRS**: separating the write model from the read model, with reads fed by events. Combines well with EDA."],
        ["**Saga**: transações distribuídas como sequência de passos e compensações coordenados por eventos.", "**Saga**: distributed transactions as a sequence of steps and compensations coordinated by events."],
      ),
      h(["Vantagens", "Advantages"]),
      ul(
        ["**Baixo acoplamento**: produtor e consumidores evoluem separadamente e desconhecem um ao outro.", "**Loose coupling**: producer and consumers evolve separately and are unaware of each other."],
        ["**Absorção de picos**: o broker guarda o acúmulo enquanto os consumidores processam no seu ritmo, protegendo sistemas lentos.", "**Spike absorption**: the broker holds the backlog while consumers process at their own pace, protecting slow systems."],
        ["**Resiliência**: se o serviço de e-mail cai, os eventos esperam e são processados na volta, sem afetar a compra.", "**Resilience**: if the email service is down, events wait and are processed on return, without affecting the purchase."],
        ["**Extensibilidade**: novos consumidores sem alterar o produtor, e até reprocessar o histórico (no Kafka, relendo o log).", "**Extensibility**: new consumers without changing the producer, and even reprocessing history (in Kafka, by rereading the log)."],
        ["**Escala independente** de cada consumidor, adicionando instâncias ao mesmo grupo.", "**Independent scaling** of each consumer, by adding instances to the same group."],
      ),
      h(["Desvantagens e cuidados", "Disadvantages and care"]),
      ul(
        ["**Consistência eventual**: por um instante, o pedido existe e o estoque ainda não foi atualizado. A interface precisa lidar com estados intermediários.", "**Eventual consistency**: for a moment the order exists and stock has not yet been updated. The interface must handle intermediate states."],
        ["**Duplicatas e reordenação**: exigem consumidores idempotentes e tolerantes à ordem.", "**Duplicates and reordering**: require idempotent, order-tolerant consumers."],
        ["**Depuração**: o fluxo está espalhado; sem ID de correlação e rastreamento distribuído, seguir uma história é detetivesco.", "**Debugging**: the flow is scattered; without a correlation ID and distributed tracing, following a story is detective work."],
        ["**Fluxo implícito**: ninguém lê em um só lugar 'o que acontece quando um pedido é criado'. Documente os fluxos e mantenha um catálogo de eventos.", "**Implicit flow**: nobody reads in one place 'what happens when an order is created'. Document flows and keep an event catalog."],
        ["**Infraestrutura nova**: operar um broker (partições, retenção, monitoramento de atraso do consumidor) é uma disciplina própria.", "**New infrastructure**: operating a broker (partitions, retention, consumer-lag monitoring) is a discipline of its own."],
        ["**Mensagens venenosas**: um evento malformado que sempre falha trava o consumidor, a menos que haja limite de tentativas e uma *dead-letter queue*.", "**Poison messages**: a malformed event that always fails blocks the consumer unless there is a retry limit and a dead-letter queue."],
      ),
      h(["Quando usar e quando evitar", "When to use it and when to avoid it"]),
      p(["Use eventos quando o produtor não precisa da resposta para continuar, quando vários sistemas reagem ao mesmo fato, quando é preciso absorver picos ou integrar sistemas com ritmos diferentes, e quando um histórico replayable tem valor (auditoria, análise, reconstrução de índices). Evite quando o usuário espera o resultado na tela para prosseguir (validar um cartão, consultar um saldo): uma chamada síncrona é mais simples e honesta. Evite também em sistemas pequenos com poucas integrações, onde um broker é mais infraestrutura do que o problema pede.", "Use events when the producer does not need the answer to continue, when several systems react to the same fact, when spikes must be absorbed or systems with different rhythms integrated, and when a replayable history has value (auditing, analysis, rebuilding indexes). Avoid them when the user waits for the result on screen to proceed (validating a card, checking a balance): a synchronous call is simpler and more honest. Also avoid them in small systems with few integrations, where a broker is more infrastructure than the problem calls for."]),
      p(["Casos reais típicos: pipelines de atividade e logs em empresas que popularizaram o Kafka (o LinkedIn o criou para isso), integração entre contextos de e-commerce, processamento de pagamentos, atualização de índices de busca e de caches, e ingestão de dados de IoT.", "Typical real cases: activity and log pipelines at companies that popularized Kafka (LinkedIn created it for this), integration between e-commerce contexts, payment processing, updating search indexes and caches, and IoT data ingestion."]),
      h(["Resumo", "Summary"]),
      ul(
        ["Eventos são fatos no passado; comandos são ordens; consultas pedem dados.", "Events are facts in the past; commands are orders; queries ask for data."],
        ["Produtores publicam, brokers guardam e entregam, consumidores reagem.", "Producers publish, brokers store and deliver, consumers react."],
        ["Use outbox para publicar com consistência e consumidores idempotentes para tolerar duplicatas.", "Use an outbox to publish consistently and idempotent consumers to tolerate duplicates."],
        ["A ordem só é garantida por partição; escolha bem a chave.", "Order is only guaranteed per partition; choose the key well."],
        ["Versione os esquemas e trate-os como API pública.", "Version schemas and treat them as a public API."],
        ["Não use eventos onde o usuário espera a resposta na hora.", "Do not use events where the user waits for the answer right away."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Evento e mensagem são a mesma coisa?** Todo evento é uma mensagem, mas nem toda mensagem é um evento: comandos e consultas também trafegam como mensagens.", "**Are an event and a message the same thing?** Every event is a message, but not every message is an event: commands and queries also travel as messages."],
        ["**Preciso de Kafka?** Não necessariamente. Para volumes moderados e roteamento flexível, RabbitMQ ou SNS/SQS bastam. O Kafka brilha com alto volume e necessidade de reler o histórico.", "**Do I need Kafka?** Not necessarily. For moderate volumes and flexible routing, RabbitMQ or SNS/SQS suffice. Kafka shines with high volume and the need to reread history."],
        ["**Como retornar um resultado ao usuário?** Responda de imediato com 'recebido' e informe o resultado depois, por polling, WebSocket ou notificação.", "**How do I return a result to the user?** Reply right away with 'received' and report the result later, via polling, WebSocket or notification."],
        ["**Eventos substituem a API REST?** Não: costumam coexistir. REST para consultas e comandos que precisam de resposta; eventos para propagar fatos.", "**Do events replace the REST API?** No: they usually coexist. REST for queries and commands needing a reply; events to propagate facts."],
      ),
      tip(["Use eventos onde o produtor não precisa da resposta para continuar. Quando o usuário espera o resultado na tela (validar um cartão), uma chamada síncrona costuma ser mais simples e honesta.", "Use events where the producer does not need the answer to continue. When the user waits for the result on screen (validating a card), a synchronous call is usually simpler and more honest."]),
    ] },

  { id: "serverless", section: "estilos", level: 1, icon: "cloud", minutes: 13,
    title: ["Serverless (FaaS)", "Serverless (FaaS)"],
    summary: ["Escrever funções e deixar a nuvem cuidar das máquinas, com seus limites e sua conta.", "Writing functions and letting the cloud handle the machines, with its limits and its bill."],
    body: [
      p(["Para colocar uma API no ar de forma tradicional, é preciso escolher o tamanho de uma máquina, instalar o sistema operacional e o runtime, configurar atualizações de segurança, dimensionar quantas cópias manter ligadas e pagar por todas elas, mesmo de madrugada, quando ninguém acessa. O modelo **serverless** propõe outra divisão de trabalho: você entrega o código e a plataforma cuida de todo o resto, executando-o apenas quando há trabalho a fazer e cobrando só por isso.", "To put an API online the traditional way, you must pick a machine size, install the operating system and runtime, configure security updates, size how many copies to keep running and pay for all of them, even at night when nobody is visiting. The **serverless** model proposes a different division of labor: you hand over the code and the platform takes care of everything else, running it only when there is work to do and billing only for that."]),
      p(["O nome engana: continua havendo servidores, só que **não são gerenciados por você**. Serverless descreve um conjunto de características: sem provisionamento de máquinas, escala automática (inclusive até zero), cobrança proporcional ao uso e alta disponibilidade embutida. Ele aparece em duas formas complementares, FaaS e BaaS, que costumam ser combinadas.", "The name is misleading: servers still exist, they are just **not managed by you**. Serverless describes a set of traits: no machine provisioning, automatic scaling (including down to zero), usage-proportional billing and built-in high availability. It comes in two complementary forms, FaaS and BaaS, which are often combined."]),
      h(["FaaS e BaaS", "FaaS and BaaS"]),
      ul(
        ["**FaaS** (*Function as a Service*): você escreve funções curtas, e a plataforma as executa em resposta a eventos. Exemplos: AWS Lambda, Google Cloud Functions, Azure Functions, Cloudflare Workers.", "**FaaS** (*Function as a Service*): you write short functions and the platform runs them in response to events. Examples: AWS Lambda, Google Cloud Functions, Azure Functions, Cloudflare Workers."],
        ["**BaaS** (*Backend as a Service*): serviços gerenciados que substituem peças do backend, como autenticação (Auth0, Cognito, Firebase Auth), banco de dados (DynamoDB, Firestore), armazenamento de objetos (S3) e filas (SQS). Você os usa por API, sem operar nada.", "**BaaS** (*Backend as a Service*): managed services that replace pieces of the backend, such as authentication (Auth0, Cognito, Firebase Auth), databases (DynamoDB, Firestore), object storage (S3) and queues (SQS). You use them via API, operating nothing."],
      ),
      h(["Como funciona uma execução", "How an execution works"]),
      p(["Cada função é registrada com um **gatilho** (*trigger*): uma requisição HTTP vinda de um API Gateway, uma mensagem em fila, um arquivo gravado em um bucket, um item alterado em uma tabela, um agendamento. Quando o evento chega, a plataforma procura um ambiente de execução já pronto para aquela função. Se existe, usa-o (**warm start**). Se não, cria um novo: baixa o pacote, inicia o runtime, executa o código de inicialização e só então chama o *handler*. Esse caminho mais longo é o **cold start**. Cada instância atende uma requisição por vez (no Lambda), de modo que 500 requisições simultâneas pedem 500 ambientes concorrentes, todos criados automaticamente.", "Each function is registered with a **trigger**: an HTTP request coming from an API Gateway, a message on a queue, a file written to a bucket, an item changed in a table, a schedule. When the event arrives, the platform looks for an execution environment already prepared for that function. If one exists, it uses it (**warm start**). If not, it creates a new one: downloads the package, starts the runtime, runs the initialization code and only then calls the *handler*. This longer path is the **cold start**. Each instance handles one request at a time (on Lambda), so 500 simultaneous requests ask for 500 concurrent environments, all created automatically."]),
      fig(["Gatilhos e funções: fluxo de um evento", "Triggers and functions: flow of an event"],
        [[node("user", ["Usuário ou upload", "User or upload"], "client")], [node("trg", ["Gatilho: API Gateway ou bucket", "Trigger: API Gateway or bucket"], "edge")], [node("fn", ["Função (FaaS)", "Function (FaaS)"], "service")], [node("db", ["Banco gerenciado", "Managed database"], "data"), node("q", ["Fila", "Queue"], "queue"), node("s3", ["Armazenamento de objetos", "Object storage"], "data")]],
        [edge("user", "trg"), edge("trg", "fn", ["evento", "event"]), edge("fn", "db"), edge("fn", "q", ["publica", "publishes"]), edge("fn", "s3")]),
      h(["Exemplo de função em TypeScript", "Function example in TypeScript"]),
      p(["O exemplo abaixo é uma função no formato do AWS Lambda que gera uma miniatura quando uma imagem é gravada em um bucket. Repare em três hábitos importantes: clientes e conexões são criados **fora** do handler, para serem reaproveitados em execuções quentes; a função é **idempotente** (a miniatura é gravada com uma chave derivada da original, então reexecutar produz o mesmo resultado); e ela não guarda estado local entre invocações.", "The example below is a function in AWS Lambda's format that generates a thumbnail when an image is written to a bucket. Note three important habits: clients and connections are created **outside** the handler, to be reused in warm executions; the function is **idempotent** (the thumbnail is written under a key derived from the original, so rerunning produces the same result); and it keeps no local state between invocations."]),
      code(`import { S3Client, GetObjectCommand, PutObjectCommand } from "@aws-sdk/client-s3";
import type { S3Event } from "aws-lambda";
import sharp from "sharp";

// created once per execution environment, reused on warm starts
const s3 = new S3Client({});

export const handler = async (event: S3Event): Promise<void> => {
  for (const rec of event.Records) {
    const bucket = rec.s3.bucket.name;
    const key = decodeURIComponent(rec.s3.object.key.replace(/\\+/g, " "));
    if (key.startsWith("thumbs/")) continue;            // avoid an infinite loop

    const obj = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
    const input = Buffer.from(await obj.Body!.transformToByteArray());
    const thumb = await sharp(input).resize(200, 200, { fit: "cover" }).jpeg().toBuffer();

    await s3.send(new PutObjectCommand({
      Bucket: bucket,
      Key: "thumbs/" + key,                             // deterministic key: idempotent
      Body: thumb,
      ContentType: "image/jpeg",
    }));
  }
};`),
      h(["Cold start e como reduzi-lo", "Cold start and how to reduce it"]),
      p(["O cold start é a crítica mais conhecida ao modelo. Seu tamanho varia de dezenas de milissegundos a alguns segundos, e depende de fatores que você controla em parte: a **linguagem** (Node.js, Python e Go iniciam rápido; Java e .NET tendem a ser mais lentos por causa da JVM e do CLR, embora técnicas como SnapStart no Lambda, que restaura um instantâneo da inicialização, reduzam muito isso), o **tamanho do pacote** (menos dependências, menos tempo de carga), a **memória configurada** (no Lambda, mais memória traz mais CPU) e o **trabalho de inicialização** (abrir conexões, carregar configuração). Se a função é colocada em uma rede privada (VPC), a plataforma moderna mitiga o custo extra, mas convém medir.", "Cold start is the model's best-known criticism. Its size ranges from tens of milliseconds to a few seconds, and depends on factors you partly control: the **language** (Node.js, Python and Go start fast; Java and .NET tend to be slower because of the JVM and CLR, although techniques such as SnapStart on Lambda, which restores a snapshot of initialization, reduce this a lot), the **package size** (fewer dependencies, less load time), the **configured memory** (on Lambda, more memory brings more CPU) and the **initialization work** (opening connections, loading configuration). If the function is placed in a private network (VPC), the modern platform mitigates the extra cost, but it is worth measuring."]),
      ul(
        ["Reduza o pacote e as dependências; empacote com um bundler e remova o que não usa.", "Shrink the package and dependencies; bundle with a bundler and remove what you do not use."],
        ["Use *provisioned concurrency* (instâncias mantidas aquecidas, ao custo de pagar por elas) para rotas sensíveis à latência.", "Use provisioned concurrency (instances kept warm, at the cost of paying for them) for latency-sensitive routes."],
        ["Faça a inicialização pesada fora do handler e adie o que não é sempre necessário.", "Do heavy initialization outside the handler and defer what is not always needed."],
        ["Em tarefas assíncronas (processamento de fila, upload), o cold start geralmente não importa.", "For asynchronous tasks (queue processing, upload), cold start usually does not matter."],
      ),
      h(["Limites que moldam o projeto", "Limits that shape the design"]),
      table([["Limite", "Limit"], ["Consequência", "Consequence"], ["Como lidar", "How to cope"]],
        [["Tempo máximo de execução (15 min no Lambda)", "Maximum execution time (15 min on Lambda)"], ["Tarefas longas não cabem em uma só invocação.", "Long tasks do not fit in a single invocation."], ["Dividir em etapas, usar orquestrador (Step Functions) ou contêineres.", "Split into steps, use an orchestrator (Step Functions) or containers."]],
        [["Sem estado local persistente", "No persistent local state"], ["Memória e disco não sobrevivem entre chamadas.", "Memory and disk do not survive between calls."], ["Guardar estado em banco, cache ou armazenamento de objetos.", "Keep state in a database, cache or object storage."]],
        [["Concorrência limitada por conta e região", "Concurrency limited per account and region"], ["Picos grandes podem ser limitados (*throttling*).", "Large spikes can be throttled."], ["Pedir aumento de cota, reservar concorrência, colocar uma fila na frente.", "Request a quota increase, reserve concurrency, put a queue in front."]],
        [["Conexões a bancos relacionais", "Connections to relational databases"], ["Milhares de funções esgotam as conexões do PostgreSQL ou MySQL.", "Thousands of functions exhaust PostgreSQL or MySQL connections."], ["Proxy de conexões (RDS Proxy, PgBouncer) ou banco pensado para serverless.", "Connection proxy (RDS Proxy, PgBouncer) or a database built for serverless."]],
        [["Tamanho de pacote e de payload", "Package and payload size"], ["Limites rígidos para código e para corpo de requisição.", "Hard limits for code and request body."], ["Camadas, imagens de contêiner e envio direto de arquivos ao armazenamento.", "Layers, container images and uploading files straight to storage."]],
      ),
      h(["Custo: pagar por invocação", "Cost: paying per invocation"]),
      p(["A cobrança típica combina dois fatores: o número de requisições e o produto da memória alocada pelo tempo de execução (GB-segundo). Para um serviço com tráfego baixo, irregular ou em rajadas, isso é muito mais barato do que manter uma máquina ligada 24 horas, e o custo cai a zero quando não há uso. O raciocínio se inverte quando a carga é alta e constante: uma instância ou contêiner bem utilizado costuma sair bem mais em conta por requisição, e o ponto de virada fica em torno de uma ocupação contínua de algumas dezenas de por cento. Existem ainda custos indiretos, como o API Gateway, o tráfego de saída, os logs e o armazenamento de dados.", "Typical billing combines two factors: the number of requests and the product of allocated memory times execution time (GB-seconds). For a service with low, irregular or bursty traffic, this is much cheaper than keeping a machine on 24 hours, and the cost drops to zero when there is no use. The reasoning flips when the load is high and constant: a well-utilized instance or container usually comes out far cheaper per request, and the tipping point sits around a sustained utilization of a few tens of percent. There are also indirect costs, such as the API Gateway, outbound traffic, logs and data storage."]),
      p(["Uma conta rápida ajuda a decidir. Suponha 1 milhão de requisições por mês, com 200 ms cada e 512 MB de memória: são 100 mil GB-segundos, um volume que cabe com folga nas faixas gratuitas ou custa centavos. Já 500 requisições por segundo o dia inteiro são mais de um bilhão por mês, e nesse regime vale comparar o preço com o de poucas instâncias dedicadas. Faça sempre o cálculo com os preços vigentes do seu provedor, pois eles mudam.", "A quick calculation helps decide. Suppose 1 million requests per month, at 200 ms each and 512 MB of memory: that is 100 thousand GB-seconds, a volume that fits comfortably in free tiers or costs cents. Meanwhile 500 requests per second all day is over a billion per month, and at that regime it pays to compare the price against a few dedicated instances. Always do the math with your provider's current prices, as they change."]),
      h(["Padrões de uso", "Usage patterns"]),
      ul(
        ["**API HTTP**: API Gateway mais funções para endpoints com tráfego irregular.", "**HTTP API**: API Gateway plus functions for endpoints with irregular traffic."],
        ["**Processamento de arquivos**: miniaturas, transcodificação, leitura de planilhas ao chegar no bucket.", "**File processing**: thumbnails, transcoding, reading spreadsheets as they land in the bucket."],
        ["**Consumidores de fila e de stream**: processar mensagens do SQS, de um stream do Kinesis ou de um tópico, com escala automática.", "**Queue and stream consumers**: processing messages from SQS, a Kinesis stream or a topic, with automatic scaling."],
        ["**Webhooks**: receber chamadas de terceiros (pagamentos, repositórios) sem manter servidor ocioso.", "**Webhooks**: receiving third-party calls (payments, repositories) without keeping an idle server."],
        ["**Tarefas agendadas e automações**: rotinas noturnas, limpezas, relatórios.", "**Scheduled tasks and automations**: nightly jobs, cleanups, reports."],
        ["**Cola entre serviços**: transformar e encaminhar eventos entre sistemas.", "**Glue between services**: transforming and routing events between systems."],
      ),
      h(["Vantagens", "Advantages"]),
      ul(
        ["**Escala automática e elástica**, inclusive até zero, sem planejar capacidade.", "**Automatic, elastic scaling**, including down to zero, without capacity planning."],
        ["**Menos operação**: sem patches de sistema operacional nem gestão de frota.", "**Less operations**: no OS patching or fleet management."],
        ["**Custo proporcional ao uso**, ideal para cargas imprevisíveis e para começar com custo mínimo.", "**Usage-proportional cost**, ideal for unpredictable loads and for starting at minimal cost."],
        ["**Disponibilidade embutida**: execução distribuída em várias zonas por padrão.", "**Built-in availability**: execution spread across several zones by default."],
        ["**Velocidade de entrega**: foco na lógica de negócio, e integração direta com os gatilhos da nuvem.", "**Delivery speed**: focus on business logic, with direct integration to cloud triggers."],
      ),
      h(["Desvantagens e quando não usar", "Disadvantages and when not to use it"]),
      ul(
        ["**Vendor lock-in**: os gatilhos, as permissões e os serviços associados são específicos de cada nuvem; migrar exige reescrever integrações. Separe a lógica de negócio do código de adaptação para reduzir o problema.", "**Vendor lock-in**: triggers, permissions and associated services are specific to each cloud; migrating requires rewriting integrations. Separate business logic from adapter code to reduce the problem."],
        ["**Latência imprevisível** por cold start em rotas de resposta muito sensível.", "**Unpredictable latency** from cold starts on very latency-sensitive routes."],
        ["**Depuração e testes locais** mais difíceis: o ambiente real é difícil de reproduzir. Use emuladores, testes de unidade da lógica pura e testes em ambiente de nuvem de desenvolvimento.", "**Harder debugging and local testing**: the real environment is hard to reproduce. Use emulators, unit tests of the pure logic and tests in a cloud development environment."],
        ["**Tarefas longas ou com muita memória** e processos que precisam manter conexões abertas (WebSockets persistentes, jogos) se encaixam mal.", "**Long-running or memory-hungry tasks** and processes that must keep connections open (persistent WebSockets, games) fit poorly."],
        ["**Carga alta e constante**: um serviço em contêiner tende a ser mais barato e previsível.", "**High, constant load**: a containerized service tends to be cheaper and more predictable."],
        ["**Arquitetura fragmentada**: dezenas de funções pequenas podem virar uma teia difícil de entender se não houver organização e observabilidade.", "**Fragmented architecture**: dozens of small functions can turn into a web hard to understand without organization and observability."],
      ),
      h(["Boas práticas", "Best practices"]),
      ul(
        ["Torne cada função **idempotente**: a plataforma pode reexecutar um evento após falha ou timeout.", "Make every function **idempotent**: the platform may rerun an event after a failure or timeout."],
        ["Coloque uma **fila na frente** de funções que chamam sistemas frágeis, para controlar a vazão e ter retentativas e dead-letter queue.", "Put a **queue in front** of functions that call fragile systems, to control throughput and get retries and a dead-letter queue."],
        ["Use **permissões mínimas** por função (um papel IAM por função, com só o necessário).", "Use **least privilege** per function (one IAM role per function, with only what is needed)."],
        ["Registre logs estruturados com ID de correlação e meça duração, erros e *throttles*.", "Emit structured logs with a correlation ID and measure duration, errors and throttles."],
        ["Defina timeouts da função menores que os dos chamadores, para não gerar execuções órfãs.", "Set function timeouts lower than the callers' to avoid orphan executions."],
      ),
      h(["Resumo", "Summary"]),
      ul(
        ["Serverless significa não gerenciar servidores; FaaS executa funções por evento, BaaS oferece serviços prontos.", "Serverless means not managing servers; FaaS runs functions per event, BaaS offers ready-made services."],
        ["Escala automática até zero e cobrança por uso são o grande atrativo.", "Automatic scaling to zero and pay-per-use are the big appeal."],
        ["Cold start, limites de tempo e falta de estado local moldam o projeto.", "Cold start, time limits and lack of local state shape the design."],
        ["Para carga baixa ou em rajadas, é barato; para carga alta e constante, contêineres costumam ganhar.", "For low or bursty load it is cheap; for high, constant load containers usually win."],
        ["Vendor lock-in é real: isole a lógica de negócio dos adaptadores.", "Vendor lock-in is real: isolate business logic from adapters."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Serverless é o mesmo que microsserviços?** Não. Microsserviços são um estilo de organização; serverless é um modelo de execução. Dá para ter microsserviços em contêineres ou em funções.", "**Is serverless the same as microservices?** No. Microservices are an organizational style; serverless is an execution model. You can have microservices in containers or in functions."],
        ["**Posso rodar um banco de dados em serverless?** Não em funções, que não guardam estado; use bancos gerenciados, alguns pensados para serverless (DynamoDB, Aurora Serverless, Firestore).", "**Can I run a database in serverless?** Not in functions, which hold no state; use managed databases, some designed for serverless (DynamoDB, Aurora Serverless, Firestore)."],
        ["**O cold start inviabiliza APIs?** Não necessariamente. Em linguagens leves e com pacote pequeno costuma ser tolerável, e há concorrência provisionada para casos críticos.", "**Does cold start make APIs unviable?** Not necessarily. In light languages with small packages it is usually tolerable, and provisioned concurrency exists for critical cases."],
        ["**Como evitar o lock-in?** Não dá para eliminá-lo, mas é possível reduzi-lo mantendo a lógica em módulos sem dependência do provedor e usando padrões abertos onde possível.", "**How do I avoid lock-in?** You cannot eliminate it, but you can reduce it by keeping logic in provider-independent modules and using open standards where possible."],
      ),
      tip(["Funções devem ser **idempotentes**: a plataforma pode reexecutar um evento após falha ou timeout. Trate a mesma entrada duas vezes sem efeito duplicado. E, antes de escolher, faça a conta dos dois cenários, função e contêiner, com os números reais da sua carga.", "Functions should be **idempotent**: the platform may rerun an event after a failure or timeout. Handle the same input twice without a duplicated effect. And before choosing, run the numbers for both scenarios, function and container, with your real load figures."]),
    ] },

  { id: "stateless-vs-stateful", section: "estilos", level: 0, icon: "memory", minutes: 12,
    title: ["Stateless e stateful", "Stateless and stateful"],
    summary: ["Onde o estado mora decide quão fácil é escalar e se recuperar de falhas.", "Where state lives decides how easy it is to scale and recover from failures."],
    body: [
      p(["Quando um usuário adiciona um item ao carrinho e, uma página depois, vai ao checkout, alguém precisa lembrar o que havia no carrinho. Esse 'algo a lembrar' é o **estado**: toda informação que precisa sobreviver entre um pedido e o próximo, como a sessão de login, o carrinho, o saldo de uma conta, o progresso de um upload ou a posição de um jogador em uma partida. A pergunta de design, uma das mais importantes de qualquer sistema distribuído, é simples de formular: **quem guarda isso, e onde?**", "When a user adds an item to the cart and, a page later, goes to checkout, someone must remember what was in the cart. That 'something to remember' is **state**: any information that must survive between one request and the next, such as the login session, the cart, an account balance, the progress of an upload or a player's position in a match. The design question, one of the most important in any distributed system, is simple to state: **who keeps it, and where?**"]),
      p(["A resposta determina como o sistema escala, como se recupera de falhas, como é implantado e quanto custa operá-lo. Por isso se fala em dois tipos de componente: os **stateless** (sem estado), que não guardam nada entre pedidos, e os **stateful** (com estado), que guardam. Um sistema real tem os dois; a arte está em concentrar o estado em poucos lugares apropriados e manter todo o resto sem estado.", "The answer determines how the system scales, how it recovers from failures, how it is deployed and how much it costs to operate. That is why we speak of two kinds of component: **stateless** ones, which keep nothing between requests, and **stateful** ones, which do. A real system has both; the art lies in concentrating state in a few appropriate places and keeping everything else stateless."]),
      h(["Serviço stateless", "Stateless service"]),
      p(["Um serviço *stateless* trata cada requisição como independente das anteriores. Tudo o que ele precisa vem **na própria requisição** (um token, um identificador, os dados do corpo) ou é buscado em um componente externo (banco, cache). Depois de responder, ele esquece. Como nenhuma instância guarda algo único, **qualquer instância pode atender qualquer pedido**, e isso é o que torna a escala horizontal tão simples.", "A *stateless* service treats each request as independent of the previous ones. Everything it needs comes **in the request itself** (a token, an identifier, the body data) or is fetched from an external component (database, cache). After answering, it forgets. Since no instance holds anything unique, **any instance can serve any request**, which is what makes horizontal scaling so simple."]),
      ul(
        ["**Escala horizontal trivial**: basta adicionar cópias atrás do balanceador de carga, sem redistribuir dados.", "**Trivial horizontal scaling**: just add copies behind the load balancer, with no data redistribution."],
        ["**Tolerância a falhas**: se uma instância cai, nenhum dado se perde e a próxima requisição vai para outra.", "**Fault tolerance**: if an instance dies, no data is lost and the next request goes to another."],
        ["**Deploys sem cerimônia**: instâncias são descartáveis e podem ser substituídas uma a uma (*rolling update*), sem 'drenar' sessões.", "**Ceremony-free deploys**: instances are disposable and can be replaced one by one (rolling update), with no need to drain sessions."],
        ["**Autoscaling e spot instances**: dá para subir e descer instâncias livremente, até usar máquinas que podem ser retiradas a qualquer momento.", "**Autoscaling and spot instances**: instances can be started and stopped freely, even using machines that may be reclaimed at any time."],
        ["**Cache e balanceamento simples**: qualquer algoritmo de balanceamento serve, como round robin.", "**Simple caching and balancing**: any balancing algorithm works, such as round robin."],
      ),
      h(["Serviço stateful", "Stateful service"]),
      p(["Um serviço *stateful* mantém dados na memória ou no disco da própria instância e depende deles para atender os pedidos. Bancos de dados, brokers de mensagens (Kafka), caches (Redis), sistemas de busca e servidores de jogo são stateful por natureza: o dado **é** o produto. As consequências são importantes. Um pedido precisa chegar à instância que tem o dado (**afinidade**). Escalar exige **particionar** (cada instância guarda uma parte) ou **replicar** (cada uma guarda uma cópia), com protocolos de consenso e de consistência. Perder uma instância pode significar perder dados, então é preciso replicação, backup e procedimentos de recuperação. E substituir uma instância é uma operação cuidadosa, pois o novo nó precisa receber o estado antes de assumir.", "A *stateful* service keeps data in memory or on the disk of its own instance and depends on it to serve requests. Databases, message brokers (Kafka), caches (Redis), search systems and game servers are stateful by nature: the data **is** the product. The consequences are significant. A request must reach the instance that holds the data (**affinity**). Scaling requires **partitioning** (each instance holds a part) or **replicating** (each holds a copy), with consensus and consistency protocols. Losing an instance may mean losing data, so replication, backups and recovery procedures are needed. And replacing an instance is a careful operation, as the new node must receive the state before taking over."]),
      table([["Aspecto", "Aspect"], ["Stateless", "Stateless"], ["Stateful", "Stateful"]],
        [["Onde está o dado", "Where the data lives"], ["Fora da instância (banco, cache, token).", "Outside the instance (database, cache, token)."], ["Dentro da instância ou do seu volume.", "Inside the instance or its volume."]],
        [["Qualquer instância atende?", "Can any instance serve?"], ["Sim.", "Yes."], ["Não: é preciso chegar à instância certa.", "No: the right instance must be reached."]],
        [["Escala", "Scaling"], ["Adicionar cópias.", "Add copies."], ["Particionar e replicar, com coordenação.", "Partition and replicate, with coordination."]],
        [["Falha de uma instância", "Instance failure"], ["Sem perda; outra assume.", "No loss; another takes over."], ["Risco de perda sem replicação.", "Risk of loss without replication."]],
        [["Deploy e atualização", "Deploy and upgrade"], ["Troca simples, uma a uma.", "Simple swap, one by one."], ["Ordenada, com sincronização e janelas de cuidado.", "Ordered, with synchronization and careful windows."]],
        [["Exemplos", "Examples"], ["API REST, servidor web, função serverless.", "REST API, web server, serverless function."], ["PostgreSQL, Redis, Kafka, Elasticsearch, servidor de jogo.", "PostgreSQL, Redis, Kafka, Elasticsearch, game server."]],
      ),
      h(["Como tornar uma aplicação stateless", "How to make an application stateless"]),
      p(["Não é possível eliminar o estado, só **empurrá-lo para fora** da camada de aplicação, para componentes projetados para guardá-lo. O resultado prático é uma arquitetura em que a camada de aplicação é um conjunto de cópias descartáveis, e a dificuldade se concentra na camada de dados, onde existem ferramentas e especialistas para tratá-la. As técnicas mais comuns:", "State cannot be eliminated, only **pushed out** of the application tier into components designed to hold it. The practical result is an architecture in which the application tier is a set of disposable copies, and the difficulty concentrates in the data tier, where tools and specialists exist to handle it. The most common techniques:"]),
      ul(
        ["**Sessões em armazenamento compartilhado**: em vez de guardar a sessão na memória do servidor, guarda-se em Redis (ou Memcached) sob um identificador enviado ao cliente por cookie. Todas as instâncias leem o mesmo Redis.", "**Sessions in shared storage**: instead of keeping the session in server memory, it is stored in Redis (or Memcached) under an identifier sent to the client by cookie. All instances read the same Redis."],
        ["**Tokens assinados (JWT)**: o próprio token carrega a identidade e as permissões, assinado pelo servidor. Qualquer instância valida a assinatura sem consultar nada. O cuidado é a revogação: um token válido vale até expirar, então se usam validades curtas e *refresh tokens*.", "**Signed tokens (JWT)**: the token itself carries identity and permissions, signed by the server. Any instance validates the signature without consulting anything. The caveat is revocation: a valid token holds until it expires, so short lifetimes and refresh tokens are used."],
        ["**Arquivos em armazenamento de objetos** (S3 e equivalentes), nunca no disco local da instância, que some quando ela é substituída.", "**Files in object storage** (S3 and equivalents), never on the instance's local disk, which vanishes when it is replaced."],
        ["**Dados em banco de dados** e filas em brokers, e não em listas ou mapas na memória do processo.", "**Data in a database** and queues in brokers, not in lists or maps in process memory."],
        ["**Configuração externa**: variáveis de ambiente ou serviço de configuração, nunca arquivos editados à mão em cada máquina.", "**External configuration**: environment variables or a config service, never files hand-edited on each machine."],
        ["**Agendamentos e jobs em um único lugar**: se todas as cópias rodam o mesmo job agendado, ele executa várias vezes; use um agendador único ou trava distribuída.", "**Schedules and jobs in a single place**: if all copies run the same scheduled job, it runs several times; use a single scheduler or a distributed lock."],
      ),
      fig(["Sessão em memória versus sessão externalizada", "In-memory session versus externalized session"],
        [[node("u1", ["Usuário", "User"], "client")], [node("lb", ["Balanceador", "Load balancer"], "edge")], [node("a1", ["App 1 (stateless)", "App 1 (stateless)"], "service"), node("a2", ["App 2 (stateless)", "App 2 (stateless)"], "service"), node("a3", ["App 3 (stateless)", "App 3 (stateless)"], "service")], [node("rd", ["Redis (sessões)", "Redis (sessions)"], "cache"), node("db", ["Banco de dados", "Database"], "data")]],
        [edge("u1", "lb"), edge("lb", "a1"), edge("lb", "a2"), edge("lb", "a3"), edge("a1", "rd"), edge("a2", "rd"), edge("a3", "rd"), edge("a2", "db")]),
      p(["No desenho acima, as três cópias da aplicação são intercambiáveis: o usuário pode ser atendido por qualquer uma a cada requisição, e a sessão está no Redis. Se a App 2 cair, ninguém percebe. Compare com a versão stateful, em que a sessão mora na memória de cada instância e o usuário precisa voltar sempre à mesma.", "In the design above, the three application copies are interchangeable: the user can be served by any of them on each request, and the session is in Redis. If App 2 dies, nobody notices. Compare with the stateful version, in which the session lives in each instance's memory and the user must always return to the same one."]),
      code(`Stateful (session in memory)         Stateless (external session)

 User --> [LB] --> [App 1]*          User --> [LB] --> [App 1] --\\
   must always return to App 1                     \\--> [App 2] ----> [Redis]
   App 1 down: session lost                         \\-> [App 3] --/
                                     any instance can serve any request`),
      h(["Sticky sessions: o atalho com custo", "Sticky sessions: the shortcut with a cost"]),
      p(["Quando a aplicação já guarda sessões na memória e não dá para reescrevê-la agora, uma saída é a **sticky session** (afinidade de sessão): o balanceador de carga identifica o usuário (por cookie ou por hash do IP) e o encaminha sempre à mesma instância. Funciona e é fácil de configurar, mas traz problemas: a carga fica desequilibrada, pois usuários pesados se concentram em algumas instâncias; a sessão se perde se a instância cair ou for substituída; o autoscaling vira menos eficaz, já que novas instâncias só recebem usuários novos; e deploys exigem drenar conexões. Trate-a como solução temporária, não como arquitetura final.", "When the application already keeps sessions in memory and cannot be rewritten right now, one way out is the **sticky session** (session affinity): the load balancer identifies the user (by cookie or IP hash) and always routes them to the same instance. It works and is easy to configure, but brings problems: load becomes unbalanced, as heavy users concentrate on a few instances; the session is lost if the instance dies or is replaced; autoscaling becomes less effective, since new instances only receive new users; and deploys require draining connections. Treat it as a temporary fix, not a final architecture."]),
      code(`# nginx: sticky routing by client IP (temporary workaround)
upstream app {
  ip_hash;
  server app1.internal:3000;
  server app2.internal:3000;
}

# preferred: no stickiness, any instance serves any request
upstream app_stateless {
  least_conn;
  server app1.internal:3000;
  server app2.internal:3000;
}`),
      h(["Sessão no servidor ou token (JWT)?", "Server session or token (JWT)?"]),
      table([["Aspecto", "Aspect"], ["Sessão em Redis", "Session in Redis"], ["JWT assinado", "Signed JWT"]],
        [["Onde está o estado", "Where the state is"], ["No servidor (Redis); o cliente guarda só o ID.", "On the server (Redis); the client holds only the ID."], ["No cliente; o servidor só valida a assinatura.", "On the client; the server only validates the signature."]],
        [["Revogação imediata", "Immediate revocation"], ["Fácil: apagar a chave.", "Easy: delete the key."], ["Difícil: exige lista de bloqueio ou validade curta.", "Hard: requires a blocklist or short lifetime."]],
        [["Consulta por requisição", "Lookup per request"], ["Uma ida ao Redis.", "One trip to Redis."], ["Nenhuma; só calcular a assinatura.", "None; just compute the signature."]],
        [["Tamanho", "Size"], ["Cookie pequeno.", "Small cookie."], ["Token maior, enviado em toda requisição.", "Larger token, sent on every request."]],
        [["Bom para", "Good for"], ["Aplicações web com controle fino de sessão.", "Web applications with fine session control."], ["APIs entre serviços e clientes móveis.", "APIs between services and mobile clients."]],
      ),
      h(["Componentes stateful em produção", "Stateful components in production"]),
      p(["Quando o estado vai para fora, ele passa a viver em bancos de dados, caches e brokers, e esses componentes precisam de cuidados próprios: replicação (líder e seguidores, ou múltiplos líderes), partição dos dados (*sharding*), backups e testes de restauração, e planos de falha (*failover*). Muitas equipes optam por serviços **gerenciados** (RDS, Cloud SQL, ElastiCache, MSK) justamente para transferir esse trabalho ao provedor.", "When state moves outside, it comes to live in databases, caches and brokers, and these components need care of their own: replication (leader and followers, or multi-leader), data partitioning (*sharding*), backups and restore tests, and failover plans. Many teams choose **managed** services (RDS, Cloud SQL, ElastiCache, MSK) precisely to hand this work to the provider."]),
      p(["No Kubernetes, a diferença aparece na escolha do objeto. Uma aplicação stateless usa um **Deployment**: pods intercambiáveis, com nomes aleatórios, criados e removidos em qualquer ordem. Um componente stateful usa um **StatefulSet**: cada pod tem uma identidade estável e ordenada (db-0, db-1, db-2), um nome de rede fixo e seu próprio **volume persistente**, que o acompanha mesmo quando o pod é recriado. Isso garante, por exemplo, que o db-1 sempre reencontre os seus dados. Ainda assim, operar bancos em Kubernetes exige operadores e experiência; muitos preferem manter os dados em serviços gerenciados fora do cluster.", "In Kubernetes the difference shows in the choice of object. A stateless application uses a **Deployment**: interchangeable pods, with random names, created and removed in any order. A stateful component uses a **StatefulSet**: each pod has a stable, ordered identity (db-0, db-1, db-2), a fixed network name and its own **persistent volume**, which follows it even when the pod is recreated. This guarantees, for example, that db-1 always finds its data again. Still, running databases on Kubernetes demands operators and experience; many prefer to keep data in managed services outside the cluster."]),
      code(`# StatefulSet: stable identity + one persistent volume per replica
apiVersion: apps/v1
kind: StatefulSet
metadata: { name: pg }
spec:
  serviceName: pg                # headless service gives pg-0.pg, pg-1.pg ...
  replicas: 3
  selector: { matchLabels: { app: pg } }
  template:
    metadata: { labels: { app: pg } }
    spec:
      containers:
        - name: postgres
          image: postgres:16
          volumeMounts: [{ name: data, mountPath: /var/lib/postgresql/data }]
  volumeClaimTemplates:
    - metadata: { name: data }
      spec:
        accessModes: ["ReadWriteOnce"]
        resources: { requests: { storage: 50Gi } }`),
      h(["Exemplo prático: carrinho de compras", "Practical example: shopping cart"]),
      p(["Considere o carrinho. Na versão ingênua, ele é um objeto na memória do servidor, ligado à sessão: funciona em desenvolvimento, mas, com duas instâncias, o usuário vê o carrinho sumir quando o balanceador o manda para a outra. Na versão stateless, o carrinho é gravado em Redis (rápido, com expiração automática) ou no banco, sob o ID do usuário ou da sessão, e qualquer instância o lê e atualiza. Para carrinhos de visitantes não identificados, uma opção é guardar o conteúdo no próprio cliente (armazenamento do navegador) e enviá-lo no checkout, aceitando limites de tamanho e de confiança.", "Consider the cart. In the naive version, it is an object in server memory, tied to the session: it works in development, but with two instances the user sees the cart vanish when the balancer sends them to the other one. In the stateless version, the cart is written to Redis (fast, with automatic expiry) or to the database, under the user or session ID, and any instance reads and updates it. For carts of anonymous visitors, one option is to keep the content on the client (browser storage) and send it at checkout, accepting limits of size and trust."]),
      code(`// stateless cart handler: all state lives in Redis
async function addToCart(req: Req, res: Res) {
  const key = "cart:" + req.userId;
  await redis.hincrby(key, req.body.sku, req.body.qty);   // atomic increment
  await redis.expire(key, 60 * 60 * 24 * 7);              // 7 days
  res.json(await redis.hgetall(key));
}
// any instance can run this handler for any user`),
      h(["Vantagens e desvantagens de cada abordagem", "Advantages and disadvantages of each approach"]),
      ul(
        ["**Stateless: vantagem** em escala, resiliência e simplicidade operacional da camada de aplicação.", "**Stateless: advantage** in scale, resilience and operational simplicity of the application tier."],
        ["**Stateless: custo**: cada requisição pode exigir buscar estado em outro componente (uma ida a mais ao Redis ou ao banco) e o token pode crescer.", "**Stateless: cost**: each request may need to fetch state from another component (an extra trip to Redis or the database) and the token can grow."],
        ["**Stateful: vantagem** em latência e em casos que exigem estado quente (jogos, edição colaborativa em tempo real, processamento de streams), em que ir ao banco a cada passo seria lento demais.", "**Stateful: advantage** in latency and in cases that require hot state (games, real-time collaborative editing, stream processing), where going to the database at each step would be too slow."],
        ["**Stateful: custo**: escala, recuperação e deploy mais difíceis, afinidade e risco de perda de dados.", "**Stateful: cost**: harder scaling, recovery and deployment, affinity and data-loss risk."],
      ),
      h(["Erros comuns", "Common mistakes"]),
      ul(
        ["Guardar sessão, cache mutável ou contadores na memória do processo e descobrir o problema só ao subir a segunda instância.", "Keeping session, mutable cache or counters in process memory and discovering the problem only when the second instance starts."],
        ["Gravar uploads no disco local do contêiner, que desaparece a cada deploy.", "Writing uploads to the container's local disk, which disappears on every deploy."],
        ["Colocar dados em JWT sem pensar em revogação, ou colocar dados sensíveis em um token que o cliente consegue ler (o JWT é assinado, não criptografado, por padrão).", "Putting data in a JWT without thinking about revocation, or sensitive data in a token the client can read (a JWT is signed, not encrypted, by default)."],
        ["Usar sticky session como solução definitiva e depois estranhar o desequilíbrio de carga.", "Using sticky sessions as the permanent solution and then wondering about load imbalance."],
        ["Tratar o Redis ou o banco como infinitamente disponível: eles são o novo ponto crítico e precisam de replicação e monitoramento.", "Treating Redis or the database as infinitely available: they are the new critical point and need replication and monitoring."],
      ),
      h(["Resumo", "Summary"]),
      ul(
        ["Estado é o que precisa ser lembrado entre requisições.", "State is what must be remembered between requests."],
        ["Stateless: qualquer instância atende qualquer pedido, o que simplifica escala e recuperação.", "Stateless: any instance serves any request, simplifying scale and recovery."],
        ["Stateful: o dado vive na instância, exigindo afinidade, replicação e cuidado.", "Stateful: data lives in the instance, requiring affinity, replication and care."],
        ["Externalize o estado em Redis, bancos e armazenamento de objetos, ou em tokens assinados.", "Externalize state in Redis, databases and object storage, or in signed tokens."],
        ["Em Kubernetes, Deployment para stateless e StatefulSet com volumes para stateful.", "On Kubernetes, Deployment for stateless and StatefulSet with volumes for stateful."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Uma API REST é stateless?** REST pede requisições autocontidas, então o servidor não deve depender de sessão em memória. Os dados, claro, ficam em um banco.", "**Is a REST API stateless?** REST calls for self-contained requests, so the server should not depend on in-memory sessions. The data, of course, lives in a database."],
        ["**Se o Redis guarda a sessão, o sistema continua stateless?** A camada de aplicação sim; o estado foi movido para um componente stateful, que deve ser replicado.", "**If Redis holds the session, is the system still stateless?** The application tier is; the state was moved to a stateful component, which must be replicated."],
        ["**WebSocket é stateful?** A conexão é: ela é presa a uma instância. Para escalar, use um canal de pub/sub (como Redis) para distribuir mensagens entre as instâncias.", "**Is a WebSocket stateful?** The connection is: it is bound to one instance. To scale, use a pub/sub channel (such as Redis) to distribute messages across instances."],
        ["**JWT ou sessão?** Sessão em Redis oferece revogação imediata; JWT dispensa consulta e serve bem entre serviços. Muitos sistemas usam os dois.", "**JWT or session?** A Redis session offers immediate revocation; JWT needs no lookup and suits service-to-service well. Many systems use both."],
      ),
      tip(["O estado não some, ele se concentra. Por isso a camada de dados (banco, cache) é onde ficam os problemas difíceis de escala e consistência, enquanto a camada de aplicação fica simples.", "State does not disappear, it concentrates. That is why the data layer (database, cache) is where the hard problems of scale and consistency live, while the application tier stays simple."]),
    ] },

  { id: "publish-subscribe", section: "estilos", level: 1, icon: "campaign", minutes: 13,
    title: ["Publish-subscribe", "Publish-subscribe"],
    summary: ["Um produtor, vários interessados, e nenhum precisa conhecer o outro.", "One producer, several interested parties, and none needs to know the others."],
    body: [
      p(["Quando um cliente conclui uma compra, vários sistemas precisam saber: o de e-mail, para confirmar; o de estoque, para baixar os itens; o de análise, para atualizar métricas; o de fidelidade, para somar pontos. Se o serviço de pedidos tivesse que chamar cada um, ficaria acoplado a todos eles, e cada novo interessado exigiria uma alteração no código dele. O padrão **publish-subscribe** (publicação e assinatura, ou **pub/sub**) resolve isso com uma ideia simples: quem tem a informação **publica** em um canal, sem endereçar a ninguém, e quem se interessa **assina** esse canal e recebe uma cópia.", "When a customer completes a purchase, several systems need to know: email, to confirm; stock, to decrement items; analytics, to update metrics; loyalty, to add points. If the orders service had to call each of them, it would be coupled to all, and each new interested party would require a change to its code. The **publish-subscribe** pattern (or **pub/sub**) solves this with a simple idea: whoever has the information **publishes** to a channel, addressing no one, and whoever is interested **subscribes** to that channel and receives a copy."]),
      p(["É o mecanismo técnico por trás da arquitetura orientada a eventos e aparece em todos os níveis: dentro de uma aplicação (um barramento de eventos em memória), entre serviços (Kafka, SNS, Google Pub/Sub) e até entre navegador e servidor (notificações em tempo real). Este artigo explica os conceitos, a diferença para as filas, as decisões de projeto, compara as principais tecnologias e mostra código.", "It is the technical mechanism behind event-driven architecture and appears at every level: inside an application (an in-memory event bus), between services (Kafka, SNS, Google Pub/Sub) and even between browser and server (real-time notifications). This article explains the concepts, the difference from queues, the design decisions, compares the main technologies and shows code."]),
      h(["Conceitos principais", "Main concepts"]),
      ul(
        ["**Publisher** (publicador): quem envia a mensagem a um tópico. Não sabe quem vai recebê-la nem quantos assinantes existem.", "**Publisher**: whoever sends the message to a topic. It does not know who will receive it or how many subscribers exist."],
        ["**Tópico** (*topic*): o canal nomeado ao qual as mensagens são publicadas, como 'pedidos.criados'.", "**Topic**: the named channel to which messages are published, such as 'orders.created'."],
        ["**Subscriber** (assinante): quem declara interesse em um tópico e recebe as mensagens.", "**Subscriber**: whoever declares interest in a topic and receives its messages."],
        ["**Assinatura** (*subscription*): o vínculo entre um tópico e um consumidor, que em muitas plataformas tem estado próprio (qual mensagem já foi entregue, o que está pendente).", "**Subscription**: the link between a topic and a consumer, which on many platforms has its own state (which message was already delivered, what is pending)."],
        ["**Broker**: o sistema que recebe, guarda e distribui as mensagens.", "**Broker**: the system that receives, stores and distributes messages."],
        ["**Fan-out**: a distribuição de uma mensagem a muitos assinantes.", "**Fan-out**: distributing one message to many subscribers."],
      ),
      fig(["Publish-subscribe: um tópico, vários assinantes", "Publish-subscribe: one topic, several subscribers"],
        [[node("pub", ["Publisher: serviço de pedidos", "Publisher: orders service"], "service")], [node("top", ["Tópico: pedidos.criados", "Topic: orders.created"], "queue")], [node("s1", ["Assinatura: e-mail", "Subscription: email"], "queue"), node("s2", ["Assinatura: estoque", "Subscription: stock"], "queue"), node("s3", ["Assinatura: analytics", "Subscription: analytics"], "queue")], [node("c1", ["Serviço de e-mail", "Email service"], "service"), node("c2", ["Serviço de estoque", "Stock service"], "service"), node("c3", ["Serviço de análise", "Analytics service"], "service")]],
        [edge("pub", "top", ["publica", "publishes"]), edge("top", "s1"), edge("top", "s2"), edge("top", "s3"), edge("s1", "c1"), edge("s2", "c2"), edge("s3", "c3")]),
      h(["Fila ou pub/sub?", "Queue or pub/sub?"]),
      p(["As duas ideias costumam ser confundidas, mas resolvem problemas diferentes. Em uma **fila** (ponto a ponto), cada mensagem é entregue a **um único** consumidor entre vários que competem por ela: serve para **dividir trabalho**. Se há mil tarefas de redimensionar imagens e dez workers, cada tarefa é processada por um deles. Em **pub/sub**, cada mensagem é entregue a **todos** os assinantes: serve para **notificar vários interessados** sobre um fato.", "The two ideas are often confused, but they solve different problems. In a **queue** (point to point), each message is delivered to **a single** consumer among several that compete for it: it serves to **split work**. If there are a thousand image-resize tasks and ten workers, each task is processed by one of them. In **pub/sub**, each message is delivered to **all** subscribers: it serves to **notify several interested parties** about a fact."]),
      table([["Aspecto", "Aspect"], ["Fila (ponto a ponto)", "Queue (point to point)"], ["Publish-subscribe", "Publish-subscribe"]],
        [["Entrega", "Delivery"], ["Cada mensagem a um consumidor.", "Each message to one consumer."], ["Cada mensagem a todos os assinantes.", "Each message to all subscribers."]],
        [["Objetivo", "Purpose"], ["Distribuir trabalho entre workers.", "Distribute work among workers."], ["Notificar vários interessados.", "Notify several interested parties."]],
        [["Conhecimento do emissor", "Sender's knowledge"], ["Sabe que envia a uma fila de trabalho.", "Knows it sends to a work queue."], ["Não sabe quantos nem quais assinantes existem.", "Does not know how many or which subscribers exist."]],
        [["Escala do consumo", "Consumption scaling"], ["Mais workers, mais vazão.", "More workers, more throughput."], ["Cada assinante escala por conta própria.", "Each subscriber scales on its own."]],
        [["Exemplo", "Example"], ["Fila de envio de e-mails marketing.", "Marketing email sending queue."], ["Evento 'pedido criado' para vários serviços.", "'Order created' event to several services."]],
      ),
      p(["Na prática, os dois se combinam. O tópico distribui para vários **grupos** de assinantes, e dentro de cada grupo as instâncias competem pelas mensagens, como numa fila. No Kafka, isso são os *consumer groups*: cada grupo recebe todas as mensagens, e dentro do grupo cada partição vai a um só consumidor. Na AWS, é o padrão clássico de **fan-out**: um tópico SNS com várias filas SQS assinando, cada fila alimentando um serviço com vários workers.", "In practice the two combine. The topic distributes to several **groups** of subscribers, and inside each group instances compete for messages, as in a queue. In Kafka these are *consumer groups*: each group receives all messages, and inside the group each partition goes to a single consumer. On AWS it is the classic **fan-out** pattern: an SNS topic with several SQS queues subscribed, each queue feeding a service with several workers."]),
      h(["Push ou pull", "Push or pull"]),
      p(["Há duas formas de uma mensagem chegar ao assinante. No modelo **push**, o broker envia a mensagem ao assinante, por exemplo chamando um endpoint HTTP (webhook) ou invocando uma função. É simples e de baixa latência, mas o assinante precisa suportar o ritmo imposto e estar disponível, e o broker precisa lidar com retentativas. No modelo **pull**, o assinante pede mensagens quando tem capacidade (*long polling* no SQS, `poll` no Kafka). Dá ao consumidor o controle da vazão e naturalmente cria contrapressão, ao custo de manter um laço de leitura. O Google Pub/Sub oferece os dois modos; o SNS é push para suas assinaturas; o Kafka é pull.", "There are two ways for a message to reach the subscriber. In the **push** model, the broker sends the message to the subscriber, for example by calling an HTTP endpoint (webhook) or invoking a function. It is simple and low-latency, but the subscriber must withstand the imposed pace and be available, and the broker must handle retries. In the **pull** model, the subscriber asks for messages when it has capacity (long polling on SQS, `poll` on Kafka). It gives the consumer control of throughput and naturally creates backpressure, at the cost of maintaining a read loop. Google Pub/Sub offers both modes; SNS is push to its subscriptions; Kafka is pull."]),
      h(["Comparação das tecnologias", "Technology comparison"]),
      table([["Tecnologia", "Technology"], ["Modelo", "Model"], ["Retenção e releitura", "Retention and replay"], ["Ordenação", "Ordering"], ["Bom para", "Good for"]],
        [["Apache Kafka", "Apache Kafka"], ["Log distribuído com partições e grupos de consumidores; pull.", "Distributed log with partitions and consumer groups; pull."], ["Retém por tempo ou tamanho configurados; qualquer grupo pode reler do início.", "Retains for configured time or size; any group can reread from the start."], ["Por partição, definida pela chave.", "Per partition, set by the key."], ["Alto volume, streaming, reprocessamento, event sourcing.", "High volume, streaming, reprocessing, event sourcing."]],
        [["AWS SNS + SQS", "AWS SNS + SQS"], ["SNS publica em tópico (push) e fan-out para filas SQS (pull) e outros destinos.", "SNS publishes to a topic (push) and fans out to SQS queues (pull) and other targets."], ["SQS retém até 14 dias, mas a mensagem some após o consumo; SNS não retém.", "SQS retains up to 14 days, but the message vanishes after consumption; SNS does not retain."], ["Filas FIFO e tópicos FIFO garantem ordem por grupo de mensagens; as padrão não.", "FIFO queues and topics guarantee order per message group; standard ones do not."], ["Integração simples na AWS, fan-out e desacoplamento sem operar servidor.", "Simple AWS integration, fan-out and decoupling without running servers."]],
        [["Google Cloud Pub/Sub", "Google Cloud Pub/Sub"], ["Tópicos e assinaturas gerenciados, push ou pull, escala automática global.", "Managed topics and subscriptions, push or pull, global automatic scaling."], ["Retenção configurável e possibilidade de reprocessar mensagens (seek/replay).", "Configurable retention and the ability to reprocess messages (seek/replay)."], ["Ordenação opcional por chave de ordenação.", "Optional ordering by ordering key."], ["Eventos em GCP, ingestão de dados, integração com Dataflow e BigQuery.", "Events on GCP, data ingestion, integration with Dataflow and BigQuery."]],
        [["Redis Pub/Sub", "Redis Pub/Sub"], ["Canais em memória; o servidor empurra a quem está conectado.", "In-memory channels; the server pushes to whoever is connected."], ["Nenhuma: quem não estiver ouvindo no instante perde a mensagem.", "None: whoever is not listening at that moment misses the message."], ["Ordem de publicação em um canal, sem durabilidade.", "Publication order on a channel, with no durability."], ["Tempo real efêmero: chat, presença, invalidação de cache. (Redis Streams adiciona log durável.)", "Ephemeral real time: chat, presence, cache invalidation. (Redis Streams adds a durable log.)"]],
        [["RabbitMQ", "RabbitMQ"], ["Exchanges roteiam para filas por regras (fanout, direct, topic).", "Exchanges route to queues by rules (fanout, direct, topic)."], ["A mensagem é removida após a confirmação; streams oferecem log.", "The message is removed after acknowledgment; streams offer a log."], ["Por fila, sujeita a reentregas.", "Per queue, subject to redeliveries."], ["Roteamento flexível, filas de trabalho e volumes moderados.", "Flexible routing, work queues and moderate volumes."]],
      ),
      h(["Decisões de projeto", "Design decisions"]),
      ul(
        ["**Garantia de entrega**: *at-most-once* (pode perder), *at-least-once* (pode duplicar, o mais comum) e *exactly-once* (restrito e caro). Prefira at-least-once com consumidores idempotentes.", "**Delivery guarantee**: at-most-once (may lose), at-least-once (may duplicate, the most common) and exactly-once (restricted and costly). Prefer at-least-once with idempotent consumers."],
        ["**Retenção**: o Kafka guarda mensagens por dias e permite reler, o que viabiliza novos consumidores e correção de bugs por reprocessamento; um broker tradicional apaga após a confirmação.", "**Retention**: Kafka keeps messages for days and allows rereading, enabling new consumers and bug fixes by reprocessing; a traditional broker deletes after acknowledgment."],
        ["**Filtros**: assinantes podem receber só o que interessa, por atributos da mensagem (filtros de assinatura do SNS e do Pub/Sub) ou por tópicos mais específicos. Filtrar no broker poupa tráfego e processamento.", "**Filters**: subscribers can receive only what interests them, by message attributes (SNS and Pub/Sub subscription filters) or by more specific topics. Filtering at the broker saves traffic and processing."],
        ["**Mensagens com falha**: após N tentativas, vão para uma *dead-letter queue* para análise, em vez de travar o fluxo.", "**Failed messages**: after N attempts they go to a dead-letter queue for analysis instead of blocking the flow."],
        ["**Ordem**: garantida apenas dentro de uma partição ou fila FIFO; escolha a chave para que eventos relacionados caiam juntos.", "**Ordering**: guaranteed only within a partition or FIFO queue; choose the key so related events land together."],
        ["**Tamanho da mensagem**: mensagens grandes sobrecarregam o broker; envie um ponteiro para o arquivo no armazenamento de objetos.", "**Message size**: large messages overload the broker; send a pointer to the file in object storage."],
        ["**Assinantes lentos**: monitore o atraso (*lag*) e escale os consumidores; um assinante atrasado não deve afetar os outros, e é por isso que cada um tem sua própria assinatura.", "**Slow subscribers**: monitor lag and scale consumers; a lagging subscriber should not affect the others, which is why each has its own subscription."],
      ),
      h(["Exemplo de código", "Code example"]),
      p(["O exemplo abaixo mostra um barramento de eventos mínimo em memória, útil para entender a mecânica e para desacoplar módulos dentro de um monolito. Em seguida, um exemplo com Kafka em TypeScript (biblioteca kafkajs), em que a **chave** garante a ordem dos eventos de um mesmo pedido e o **groupId** define qual conjunto de instâncias compartilha as mensagens.", "The example below shows a minimal in-memory event bus, useful to grasp the mechanics and to decouple modules inside a monolith. Next, a Kafka example in TypeScript (kafkajs library), where the **key** guarantees the order of events of the same order and the **groupId** defines which set of instances shares the messages."]),
      code(`// minimal in-memory pub/sub
type Handler<T> = (payload: T) => void | Promise<void>;

class EventBus {
  private subs = new Map<string, Set<Handler<any>>>();

  subscribe<T>(topic: string, fn: Handler<T>): () => void {
    if (!this.subs.has(topic)) this.subs.set(topic, new Set());
    this.subs.get(topic)!.add(fn);
    return () => this.subs.get(topic)!.delete(fn);       // unsubscribe
  }

  async publish<T>(topic: string, payload: T): Promise<void> {
    const handlers = [...(this.subs.get(topic) ?? [])];
    // fan-out: one failing subscriber does not block the others
    await Promise.allSettled(handlers.map((fn) => fn(payload)));
  }
}

const bus = new EventBus();
bus.subscribe("orders.created", (o: { id: string }) => console.log("email for", o.id));
bus.subscribe("orders.created", (o: { id: string }) => console.log("stock for", o.id));
await bus.publish("orders.created", { id: "ord_42" });`),
      code(`// Kafka with kafkajs: publisher and one consumer group
import { Kafka } from "kafkajs";

const kafka = new Kafka({ clientId: "orders", brokers: ["kafka:9092"] });

// publisher
const producer = kafka.producer();
await producer.connect();
await producer.send({
  topic: "orders.created",
  messages: [{ key: "ord_42", value: JSON.stringify({ eventId: "evt_981", orderId: "ord_42" }) }],
});                                    // same key => same partition => ordered

// subscriber: instances sharing groupId split the partitions
const consumer = kafka.consumer({ groupId: "email-service" });
await consumer.connect();
await consumer.subscribe({ topic: "orders.created", fromBeginning: false });
await consumer.run({
  eachMessage: async ({ message }) => {
    const evt = JSON.parse(message.value!.toString());
    // idempotent handling: ignore evt.eventId if already processed
    await sendConfirmationEmail(evt.orderId);
  },
});
// another groupId (e.g. "stock-service") would receive every message too`),
      h(["Filtros e roteamento", "Filters and routing"]),
      p(["Quando muitos tipos de evento passam pelo mesmo tópico, nem todo assinante quer tudo. Há três abordagens. A primeira é usar **tópicos granulares** (um por tipo de evento), o que é simples, mas multiplica canais. A segunda é **filtrar por atributos** no próprio broker, de modo que o assinante receba só mensagens com, por exemplo, país igual a BR ou valor acima de um limite; é o que oferecem as políticas de filtro do SNS e as assinaturas filtradas do Google Pub/Sub. A terceira é **roteamento por padrão**, como o dos exchanges do tipo *topic* do RabbitMQ, em que a chave de roteamento 'pedido.criado.br' casa com padrões como 'pedido.*.br'.", "When many event types pass through the same topic, not every subscriber wants everything. There are three approaches. The first is to use **granular topics** (one per event type), which is simple but multiplies channels. The second is **filtering by attributes** at the broker, so the subscriber receives only messages with, for example, country equal to BR or a value above a threshold; this is what SNS filter policies and Google Pub/Sub filtered subscriptions offer. The third is **pattern routing**, such as RabbitMQ topic exchanges, where the routing key 'order.created.br' matches patterns like 'order.*.br'."]),
      h(["Vantagens e desvantagens", "Advantages and disadvantages"]),
      ul(
        ["**Desacoplamento no conhecimento**: o publicador não sabe quem escuta; novos assinantes entram sem tocar nele.", "**Decoupling in knowledge**: the publisher does not know who listens; new subscribers join without touching it."],
        ["**Desacoplamento no tempo**: com um broker durável, o assinante pode estar fora do ar e receber depois.", "**Decoupling in time**: with a durable broker, the subscriber may be offline and receive later."],
        ["**Escalabilidade**: assinantes e publicadores escalam de forma independente.", "**Scalability**: subscribers and publishers scale independently."],
        ["**Extensibilidade**: o sistema ganha comportamentos novos apenas acrescentando assinantes.", "**Extensibility**: the system gains new behaviors simply by adding subscribers."],
        ["**Contrapartida: fluxo implícito**: difícil saber, olhando um serviço, quem reage ao que ele publica.", "**Trade-off: implicit flow**: hard to tell, looking at one service, who reacts to what it publishes."],
        ["**Contrapartida: contrato oculto**: o formato da mensagem continua sendo um acoplamento; mudá-lo pode quebrar assinantes desconhecidos.", "**Trade-off: hidden contract**: the message format is still a coupling; changing it can break unknown subscribers."],
        ["**Contrapartida: garantias sutis**: duplicatas, ordem parcial e atraso exigem consumidores bem escritos.", "**Trade-off: subtle guarantees**: duplicates, partial ordering and delay demand well-written consumers."],
      ),
      h(["Onde aparece", "Where it appears"]),
      ul(
        ["Notificações a múltiplos canais (e-mail, push, SMS) a partir de um mesmo fato.", "Notifications across multiple channels (email, push, SMS) from one fact."],
        ["Atualização de índices de busca, caches e réplicas de leitura quando um dado muda.", "Updating search indexes, caches and read replicas when data changes."],
        ["Tempo real: cotações, placares e chat distribuindo mensagens a milhares de conexões (Redis Pub/Sub, por exemplo).", "Real time: quotes, scores and chat distributing messages to thousands of connections (Redis Pub/Sub, for example)."],
        ["Pipelines de dados: eventos de cliques e de logs alimentando análise em lote e em tempo real.", "Data pipelines: click and log events feeding batch and real-time analytics."],
        ["Integração entre sistemas: um sistema legado publica mudanças e vários consumidores novos se conectam.", "System integration: a legacy system publishes changes and several new consumers connect."],
      ),
      h(["Erros comuns", "Common mistakes"]),
      ul(
        ["Usar pub/sub quando se queria uma fila de trabalho, e acabar com todo worker processando todas as tarefas.", "Using pub/sub when a work queue was wanted, and ending up with every worker processing every task."],
        ["Usar Redis Pub/Sub para eventos que não podem ser perdidos: ele não guarda mensagens.", "Using Redis Pub/Sub for events that cannot be lost: it does not store messages."],
        ["Esquecer a idempotência e cobrar duas vezes quando o broker reentrega.", "Forgetting idempotency and charging twice when the broker redelivers."],
        ["Escolher a chave de ordenação errada e perder a sequência de eventos relacionados.", "Picking the wrong ordering key and losing the sequence of related events."],
        ["Não configurar dead-letter queue e deixar uma mensagem venenosa bloquear o consumidor.", "Not configuring a dead-letter queue and letting a poison message block the consumer."],
        ["Publicar eventos sem versão nem documentação, e depois não conseguir mudá-los.", "Publishing events with no version or documentation, and later being unable to change them."],
      ),
      h(["Resumo", "Summary"]),
      ul(
        ["Pub/sub entrega cada mensagem a todos os assinantes de um tópico; fila entrega a um consumidor só.", "Pub/sub delivers each message to all subscribers of a topic; a queue delivers to one consumer only."],
        ["Os dois se combinam: tópico com fan-out para filas ou grupos de consumidores.", "The two combine: a topic fanning out to queues or consumer groups."],
        ["Push dá simplicidade; pull dá controle de vazão.", "Push gives simplicity; pull gives throughput control."],
        ["Kafka retém e permite releitura; SNS/SQS e Pub/Sub são gerenciados; Redis Pub/Sub é efêmero.", "Kafka retains and allows replay; SNS/SQS and Pub/Sub are managed; Redis Pub/Sub is ephemeral."],
        ["Projete para duplicatas, ordem parcial e falhas, e trate o formato da mensagem como API pública.", "Design for duplicates, partial order and failures, and treat the message format as a public API."],
      ),
      h(["Perguntas frequentes", "FAQ"]),
      ul(
        ["**Pub/sub e event-driven são o mesmo?** Pub/sub é o mecanismo de distribuição; a arquitetura orientada a eventos é o estilo de projeto que o usa para modelar o sistema como reações a fatos.", "**Are pub/sub and event-driven the same?** Pub/sub is the distribution mechanism; event-driven architecture is the design style that uses it to model the system as reactions to facts."],
        ["**Posso garantir ordem global?** Em geral não de forma escalável; use ordem por chave (partição ou grupo de mensagens) e projete para isso.", "**Can I guarantee global order?** Generally not in a scalable way; use per-key order (partition or message group) and design for it."],
        ["**Qual escolher para começar?** Se está na AWS ou GCP, o serviço gerenciado (SNS/SQS ou Pub/Sub) reduz a operação. Para alto volume e releitura, Kafka.", "**Which to choose to start?** If you are on AWS or GCP, the managed service (SNS/SQS or Pub/Sub) reduces operations. For high volume and replay, Kafka."],
        ["**O que acontece se um assinante está offline?** Com um broker durável, as mensagens esperam na assinatura; com Redis Pub/Sub, ele as perde.", "**What happens if a subscriber is offline?** With a durable broker, messages wait in the subscription; with Redis Pub/Sub, it misses them."],
      ),
      tip(["Pub/sub desacopla no tempo e no conhecimento, mas o contrato (nome e formato do evento) continua sendo um acoplamento. Trate-o como uma API pública: versione e documente.", "Pub/sub decouples in time and in knowledge, but the contract (event name and format) is still coupling. Treat it like a public API: version and document it."]),
    ] },
];
